// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {OracleLib} from "../src/core/OracleLib.sol";
import {GlobalConfig} from "../src/core/GlobalConfig.sol";
import {YieldMath} from "../src/lib/YieldMath.sol";
import {CoreVaultReferral} from "./CoreVaultReferral.sol";

/// @title  CoreVaultFarming -- farming core (deposit / claim / redeem)
/// @notice Main BNB deposit, yield claim and redemption flows; referral distribution is implemented by sub-contracts via the virtual _onClaimYield.
/// @dev 3rd generation (facet split version) rewritten version -- for evidence and limitations see the top note of CoreVaultStorage.sol.
///      Differences from the 2nd generation (all backed by documentation):
///        - deposit bound validation changed from `GlobalConfig` constants to **storage variables**
///          (`_minDepositBnb`/`_maxDepositBnb`/`_minDepositUsd`/`_maxDepositUsd`) --
///          per the "change list" in `docs/03-deploy/mainnet-test-deployment-guide.md`.
///        - **fixed the `_getMcapUsd` unit/dimension error** -- per section 6 of the same document (with PoC evidence).
///      The **view functions** of this layer in the 2nd generation are not included (they were never in this layer either); views live in
///      `src/core/CoreVaultViewFacet.sol`.
///      WARNING: the inheritance base changed from the 2nd generation's `CoreVaultStaking` to **`CoreVaultReferral`** --
///      this is the precondition for the facet split to work. Evidence:
///        (1) the top comment of `src/CoreVault.sol` states two chains:
///           `CoreVault` = Storage->Admin->Referral->**Staking** + 31 forwarding wrappers;
///           `CoreVaultLogicFacet` = Storage->Admin->Referral->**Farming->FarmingReferral**.
///           If Farming still inherited Staking, LogicFacet would be forced to pull in the whole Staking layer.
///        (2) on-chain `logicFacet` (`0xca3116b0...`) measured: at runtime **14,925 B / 34 selectors**,
///           among which there are **no** `stakeA` / `stakeB` / `donateOskPool` / `donateFistPool`
///           => the real LogicFacet indeed does not contain Staking.
///        (3) this layer has **zero dependency** on Staking (verified function by function): all calls land only on
///           Storage (storage/helpers) / Admin (`_payoutStaking`) / Referral (`_checkLevelUpStaking`).
abstract contract CoreVaultFarming is CoreVaultReferral {
  // Pitfall: a Solidity using-for directive is scoped to the current contract only (not inherited by derived contracts),
  //       so this file must declare it itself; otherwise IERC20.safeTransferFrom/safeTransfer are not visible.
  using SafeERC20 for IERC20;

  /// @dev Empty virtual implementation -- the body is overridden by CoreVaultFarmingReferral
  function _onClaimYield(address, uint256, uint256) internal virtual returns (uint256, uint256) { return (0, 0); }

  /// @dev Requirements doc section 2: event emitted when the 2.5% withdrawal tax buying FIST and injecting it into the FIST staking pool fails
  event FistInjectFailed(uint256 oskAmount);

  // ── Internal helpers ──

  function _markExited(address user) internal {
    _fvUsers[user].flags |= 1;
    uint256 len = _fvUsers[user].positions.length;
    if (len > 0) {
      Position storage p = _fvUsers[user].positions[len - 1];
      if (p.flags & 1 == 0) p.flags |= 1;
    }
  }

  function _calcPendingYield(Position storage p, uint256 mcapUsd) private view returns (uint256) {
    if ((p.flags & 1) != 0 || block.timestamp <= p.lastRewardTime) return 0;
    unchecked {
      uint256 elapsed = block.timestamp - p.lastRewardTime;
      uint256 ratePerSec = YieldMath.apyPerSecond(mcapUsd, _tierUppers);
      uint256 interestUsd = YieldMath.calcInterest(p.principalUsd, ratePerSec, elapsed);
      uint256 maxEarnUsd = p.principalUsd * GlobalConfig.MAX_MULTIPLIER;
      if (p.earnedUsd >= maxEarnUsd) return 0;
      // WARNING: the **static yield is truncated here** at 3x max-out: interest stops at 3x, instead of "overflowing" the difference to aStaking.
      //   Consequence: the pendingUsd received by `_processYieldPayout` is already <= (3x - accrued),
      //        so the **static part of its overflowUsd is always 0** -- the overflow leg only absorbs the truncated referral/team difference.
      //   Evidence: Requirement L90 "static yield + team yield = 3x max-out"; client-confirmed policy on 2026-09-23.
      //   Regression: test/ThreeXMaxOutAudit.t.sol::test_Farming_3x_StaticPath_TruncatesInsteadOfOverflowing
      if (p.earnedUsd + interestUsd > maxEarnUsd) return maxEarnUsd - p.earnedUsd;
      return interestUsd;
    }
  }

  /// @dev The "LP market cap (USD)" needed for tier computation
  /// @notice WARNING: 3rd generation **fix**: the 2nd generation wrongly used **multiplication** (`ar × aPerUsd / 1e18`), with unit/dimension OSK^2/USD.
  ///   The correct conversion is **division** -- `aPerUsd` means "how many OSK per 1 USD", so USD = OSK / aPerUsd.
  /// Evidence: `docs/03-deploy/mainnet-test-deployment-guide.md` section 6 (with PoC: at a 1:1 price multiplication and division are indistinguishable,
  ///   but at real prices the error can reach 9×10^10 times, a +400% yield).
  /// Contrast (the existing correct form elsewhere in the repo, both division):
  ///   `_depositBNBCore`: bnbAmount × 1e18 / avgWbnbPerUsd
  ///   `_depositFistCore`: fistAmount × 1e18 / avgBRate
  /// Pitfall: the 2nd generation read aWbnbPair/bWbnbPair (the dual WBNB pairs); the 3rd generation price sources are now
  ///   the OSK/FIST pair + FIST/USDT pair (see OracleState in src/core/OracleLib.sol).
  ///   So here we take the OSK reserve of aOskFistPair, then convert to USD via aPerUsd.
  function _getMcapUsd() private view returns (uint256) {
    if (address(_oracle.aOskFistPair) == address(0)) return 0;
    uint256 aPerUsd = OracleLib.getAPerUsdView(_oracle);
    if (aPerUsd == 0) return 0;
    (uint112 r0, uint112 r1,) = _oracle.aOskFistPair.getReserves();
    uint256 ar = _oracle.aOskFistPair.token0() == address(aToken) ? uint256(r0) : uint256(r1);
    // Division: USD = OSK reserve / (OSK per USD)
    return Math.mulDiv(ar, 1e18, aPerUsd, Math.Rounding.Floor);
  }

  function _pendingYield(Position storage p) private returns (uint256) {
    OracleLib.updateATwap(_oracle);
    return _calcPendingYield(p, _getMcapUsd());
  }

  // ── Deposit ──

  function depositBNB(address referrer) external payable {
    _guardEnter();
    _requireValidReferrer(referrer);
    _depositBNBCore(msg.sender, msg.value, referrer);
    _guardExit();
  }

  /// @notice FIST deposit into farming (Requirement 2.0 section 2, "FIST on-chain mining mechanism 2")
  /// @dev The single-deposit bounds are defined by "gold-standard real-time USD value" -- the bounds come from the **currently effective storage variables**
  ///      (`_minDepositUsd` / `_maxDepositUsd`); production defaults to 100 - 10000 USD, and the test build lowers them via owner.
  ///      The caller must first approve fistAmount to this contract.
  /// Design intent: shares the same position/yield/3x max-out/redemption formulas with the BNB channel -- the only differences are the deposit token and the treasury-side fund allocation path,
  ///           so position principal is always converted to a USD denomination and the two channels have an identical yield policy.
  /// Pitfall: except for genesis addresses, a valid referrer must be provided -- reusing the same _requireValidReferrer as the BNB channel,
  ///       which enforces Requirement 2.0's "all users must first lock their relationship through the farming module before participating in other modules' business".
  /// Pitfall: redemption is always settled in BNB (Requirement 2.0 section 2), regardless of the deposit token.
  function depositFIST(address referrer, uint256 fistAmount) external {
    _guardEnter();
    _requireValidReferrer(referrer);
    _depositFistCore(msg.sender, fistAmount, referrer);
    _guardExit();
  }

  function _depositBNBCore(address user, uint256 bnbAmount, address referrer) internal {
    // Pitfall: read the storage variables, not the GlobalConfig constants -- otherwise the owner's setDepositBounds has no effect.
    if (bnbAmount < _minDepositBnb || bnbAmount > _maxDepositBnb) revert CoreVault_InvalidAmount();
    (uint256 spotARate,,) = OracleLib.getAllPrices(_oracle);
    (, , uint256 avgWbnbPerUsd) = OracleLib.getAccountingPrices(_oracle);
    if (avgWbnbPerUsd == 0 || spotARate == 0) revert CoreVault_PriceUnavailable();
    uint256 usdAmount = Math.mulDiv(bnbAmount, 1e18, avgWbnbPerUsd, Math.Rounding.Floor);
    // Valid-user threshold: the BNB channel is judged by **token count** (already validated above as `bnbAmount >= _minDepositBnb`) => pass 0 on the USD side.
    uint256 pid = _openPosition(user, usdAmount, spotARate, referrer, 0, 0);
    treasury.allocateDeposit{value: bnbAmount}(user, bnbAmount, 1500);
    emit BnbDeposited(user, bnbAmount, usdAmount, pid);  }

  function _depositFistCore(address user, uint256 fistAmount, address referrer) internal {
    if (fistAmount == 0) revert CoreVault_InvalidAmount();
    (uint256 spotARate, , ) = OracleLib.getAllPrices(_oracle);
    (, uint256 avgBRate, ) = OracleLib.getAccountingPrices(_oracle);
    if (spotARate == 0 || avgBRate == 0) revert CoreVault_PriceUnavailable();
    // Gold-standard pricing: FIST amount -> USD value (bPerUsd = number of FIST corresponding to 1 USD)
    uint256 usdAmount = Math.mulDiv(fistAmount, 1e18, avgBRate, Math.Rounding.Floor);
    // Pitfall: same as _depositBNBCore -- read the storage variables so the test build's small bounds take effect.
    if (usdAmount < _minDepositUsd || usdAmount > _maxDepositUsd) {
      revert CoreVault_InvalidAmount();
    }
    uint256 pid = _openPosition(user, usdAmount, spotARate, referrer, 1, GlobalConfig.VALID_USER_MIN_USD);
    // Fund allocation is executed by the treasury: 10% buys and burns FISTDAO / 20% insurance pool FIST reserve / 70% forms OSK+FIST LP
    // Pitfall: transfer FIST into the treasury first, then call -- the treasury uses "the balance before this transfer" as the baseline to sweep swap change and LP dust.
    IERC20(address(bToken)).safeTransferFrom(user, address(this), fistAmount);
    IERC20(address(bToken)).safeTransfer(address(treasury), fistAmount);
    treasury.allocateFistDeposit(user, fistAmount, GlobalConfig.LP_SLIPPAGE_BP);
    emit FistDeposited(user, fistAmount, usdAmount, pid);
  }

  /// @dev Unified position-opening pipeline (shared by the BNB / FIST channels)
  ///      Pitfall: CEI -- everything in this function is a state change (registration/quota/position/team performance), with no external calls,
  ///            so the caller can safely perform treasury fund allocation afterwards.
  /// @param validFloorUsd the USD threshold for a "valid direct referral" -- **passed per channel** (client ruling on 2026-09-27):
  ///        the BNB channel passes 0 (its lower bound is already validated by BNB **token count** in `_depositBNBCore`),
  ///        the FIST channel passes `GlobalConfig.VALID_USER_MIN_USD` (100 USD).
  ///        Pitfall: do not use a single shared USD constant for both channels -- BNB price fluctuation can make 0.1 BNB worth less than 100 USD.
  function _openPosition(
    address user, uint256 usdAmount, uint256 spotARate, address referrer,
    uint8 depositToken, uint256 validFloorUsd
  )
    internal returns (uint256 pid)
  {
    _register(user, referrer);
    FvUser storage fv = _fvUsers[user];
    bool wasExited = (fv.flags & 1) != 0;
    if (wasExited) {
      // Order-stacking rule: rebuilding after a 3x max-out requires the new order's USD amount to be **>= the principal of the last order before max-out**.
      //   Evidence: client-confirmed on 2026-09-24 -- "the user must rebuild a new order with a usd amount greater than or equal to the old order
      //         before entitlements can be restored"; same semantics as the staking side's `amount >= s.lastPrincipal` in design doc section 7.3.
      // Pitfall: must be read **before** `fv.positions.push` -- after push the last element is the new order.
      // Pitfall: must be judged before clearing the max-out flag -- use `wasExited` (set by _markExited).
      uint256 len = fv.positions.length;
      if (len > 0 && usdAmount < fv.positions[len - 1].principalUsd) revert CoreVault_InvalidAmount();
      fv.flags &= ~uint8(1);
    }
    if (fv.positions.length > 0) {
      Position storage _last = fv.positions[fv.positions.length - 1];
      if (_last.flags & 1 == 0) revert CoreVault_ActivePositionExists(fv.positions.length - 1);
    }
    pid = fv.positions.length;
    fv.positions.push(Position({
      principalUsd: usdAmount,
      principalA: Math.mulDiv(usdAmount, spotARate, 1e18, Math.Rounding.Floor),
      earnedYield: 0, earnedUsd: 0,
      lastRewardTime: block.timestamp,
      depositTime: block.timestamp,
      flags: wasExited ? 2 : 0,
      redeemableUsd: 0,
      snapshotDirect: fv.earnedDirect,
      snapshotTeam: fv.earnedTeam,
      depositToken: depositToken
    }));
    unchecked { fv.totalInvestedUsd += usdAmount; }
    _onInvest(user, usdAmount, validFloorUsd);
  }

  /// @param validFloorUsd the USD threshold for a "valid direct referral", passed per channel by `_openPosition` (see its comment).
  function _onInvest(address user, uint256 usdAmount, uint256 validFloorUsd) internal {
    if (!isRegistered(user) || usdAmount == 0) return;
    FvUser storage u = _fvUsers[user];
    uint256 prevMax = u.maxUsd;
    if (usdAmount <= prevMax) return;
    unchecked {
      uint256 delta = usdAmount - prevMax;
      u.maxUsd = usdAmount;
      bool isFirst = prevMax == 0;
      address _ref = _refs[user].referrer;
      if (_ref != address(0) && isFirst && usdAmount >= validFloorUsd) {
        if (_markFirstInvest(user)) {
          if (_refs[_ref].validDirectCount < GlobalConfig.MAX_REFERRAL_GEN) _incValidDirects(_ref);
        }
      }
      address curr = _ref;
      for (uint16 d = 0; d < GlobalConfig.MAX_TEAM_DEPTH && curr != address(0); d++) {
        _fvUsers[curr].totalTeamUsd += delta;
        if (d == 0) _fvUsers[curr].totalDirectUsd += delta;
        _checkLevelUpStaking(curr);
        curr = _refs[curr].referrer;
      }
    }
  }

  // ── Claim yield ──

  function claimYield(uint256 positionId) external {
    _guardEnter();
    _claimYieldCore(msg.sender, positionId);
    _guardExit();
  }

  function claimYieldActive() external {
    _guardEnter();
    _claimYieldCore(msg.sender, _findActivePosition(msg.sender));
    _guardExit();
  }

  function _findActivePosition(address user) internal view returns (uint256) {
    FvUser storage fv = _fvUsers[user];
    uint256 len = fv.positions.length;
    if (len == 0) revert CoreVault_NoActivePosition();
    uint256 lastIdx = len - 1;
    if (fv.positions[lastIdx].flags & 1 != 0) revert CoreVault_NoActivePosition();
    return lastIdx;
  }

  function _claimYieldCore(address user, uint256 positionId) internal {
    FvUser storage fv = _fvUsers[user];
    if (positionId >= fv.positions.length) revert CoreVault_InvalidAmount();
    Position storage p = fv.positions[positionId];
    if (p.flags & 1 != 0) revert CoreVault_InvalidAmount();
    if (block.timestamp - p.lastRewardTime < GlobalConfig.CLAIM_COOLDOWN) revert CoreVault_InvalidAmount();
    uint256 pendingUsd = _pendingYield(p);
    if (pendingUsd == 0) return;
    _processYieldPayout(user, positionId, fv, p, pendingUsd);
  }

  function _processYieldPayout(
    address user, uint256 positionId, FvUser storage fv, Position storage p, uint256 pendingUsd
  ) internal {
    uint256 totalEarnedUsd = p.earnedUsd + pendingUsd
      + (fv.earnedDirect - p.snapshotDirect)
      + (fv.earnedTeam - p.snapshotTeam);
    uint256 overflowUsd;
    if (totalEarnedUsd >= p.principalUsd * GlobalConfig.MAX_MULTIPLIER) {
      uint256 maxPayoutUsd = p.principalUsd * GlobalConfig.MAX_MULTIPLIER;
      uint256 referralDelta = (fv.earnedDirect - p.snapshotDirect) + (fv.earnedTeam - p.snapshotTeam);
      uint256 consumed = p.earnedUsd + referralDelta;
      uint256 cappedPending = consumed < maxPayoutUsd ? maxPayoutUsd - consumed : 0;
      overflowUsd = pendingUsd > cappedPending ? pendingUsd - cappedPending : 0;
      pendingUsd = cappedPending;
      p.flags |= 1;
      _markExited(user);
      emit PositionClosed(user, positionId, 1);
    }
    p.earnedUsd += pendingUsd;
    p.lastRewardTime = block.timestamp;
    (uint256 avgARate,,) = OracleLib.getAccountingPrices(_oracle);
    if (avgARate == 0) revert CoreVault_PriceUnavailable();
    uint256 payoutA = Math.mulDiv(pendingUsd, avgARate, 1e18, Math.Rounding.Floor);
    unchecked { p.earnedYield += payoutA; fv.totalEarned += payoutA; }
    (, uint256 overflowFromClaim) = _onClaimYield(user, pendingUsd, avgARate);
    overflowUsd += overflowFromClaim;
    uint256 fee = Math.mulDiv(payoutA, GlobalConfig.FEE_BP_TOTAL, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
    // Requirement 2.0 section 2, farming rule 1: 5% withdrawal tax = "2.5% buys FIST and injects it into the FIST staking pool" + "2.5% goes to the five mining pool nodes split equally".
    // Pitfall: use the named constants (FEE_BP_ASTAKING / FEE_BP_WALLET2) rather than a hard-coded `fee / 2` --
    //   so the split policy is traceable and separately adjustable, and stays consistent with the GlobalConfig SSOT.
    //   Numerically floor(fee × 250 / 500) is bit-for-bit equivalent to `fee / 2` and does not change existing behavior.
    uint256 toFistPool = Math.mulDiv(fee, GlobalConfig.FEE_BP_ASTAKING, GlobalConfig.FEE_BP_TOTAL, Math.Rounding.Floor);
    uint256 toFeewallet1 = fee - toFistPool;
    uint256 net = payoutA - fee;
    if (net > 0) treasury.payoutReward(user, net);
    // Requirements doc section 2: 2.5% withdrawal tax -> buy OSK->USDT->FIST and inject into the FIST staking pool (only via FIST/USDT, the deepest liquidity)
    // Pitfall: use try/catch to keep yield claiming available -- an external DEX failure should not block the user's claim; but a failure event must be emitted, not silently swallowed.
    if (toFistPool > 0) {
      try treasury.swapOskToFistAndInject(toFistPool, GlobalConfig.LP_SLIPPAGE_BP) {}
      catch { emit FistInjectFailed(toFistPool); }
    }
    // Requirement 2.0 section 2: 2.5% withdrawal tax -> equal dividend to the five mining pool nodes
    // Wiring: feewallet1 must point to the 5-node dividend distribution contract (i.e. BWalletDistributor5 of the pangu project),
    //       which splits the OSK equally among the 5 mining pool nodes; this contract only transfers out the 2.5% in the original token and does no node management.
    if (toFeewallet1 > 0 && feewallet1 != address(0)) treasury.payoutReward(feewallet1, toFeewallet1);
    // Node requirements doc section 1, entitlements: 30% of network-wide static revenue is injected into the node mining pool -> NodePoolDistributor four-pool weighting 5/5/10/10.
    // Policy (confirmed): it is an **additional** expense (1.0 "200% gross expense"), not deducted from the user's share, and **does not participate** in 3x max-out accounting.
    // Pitfall: the accrual base uses the **pendingUsd actually confirmed paid** for this claim (i.e. the value after 3x max-out trimming) --
    //   the node pool should not share revenue that was "never paid to the user", otherwise the node leg would exceed the real 30% of static revenue.
    // Implementation: **shared with the staking module** via `CoreVaultStorage::_payoutNodePoolLeg` -- to avoid the two modules' policies diverging.
    _payoutNodePoolLeg(pendingUsd, avgARate);
    // The "overflow" part of 3x max-out -> aStaking staking pool.
    // WARNING: reachability (verified 2026-09-23): this branch **only carries the difference** by which referral/team rewards were truncated by `_remaining3xCap`
    //   (i.e. the overflowFromClaim returned by `_onClaimYield`). **Static yield produces no overflow** --
    //   `_calcPendingYield` already truncates it at the 3x boundary to `principal×3 - accrued`, so here
    //   `pendingUsd <= cappedPending` always holds -> the static part contributes 0.
    //   Semantics: static yield is "interest stops at 3x", not "overflow to aStaking".
    //   Regression: test/ThreeXMaxOutAudit.t.sol's
    //     - test_Farming_3x_StaticPath_TruncatesInsteadOfOverflowing (zero static overflow)
    //     - test_Farming_3x_OverflowFromReferralTruncation        (referral-truncation overflow reachable)
    if (overflowUsd > 0 && address(treasury.aStaking()) != address(0)) {
      uint256 overflowA = Math.mulDiv(overflowUsd, avgARate, 1e18, Math.Rounding.Floor);
      treasury.payoutReward(treasury.aStaking(), overflowA);
      totalAPoolRewards += overflowA;
    }
    emit YieldClaimed(user, positionId, net);
  }

  // ── Redemption ──

  function redeemPrincipal(uint256 positionId) external {
    _guardEnter();
    _redeemPrincipalCore(msg.sender, positionId);
    _guardExit();
  }

  function redeemPrincipalActive() external {
    _guardEnter();
    _redeemPrincipalCore(msg.sender, _findActivePosition(msg.sender));
    _guardExit();
  }

  function _redeemPrincipalCore(address user, uint256 positionId) internal {
    FvUser storage fv = _fvUsers[user];
    if (positionId >= fv.positions.length) revert CoreVault_InvalidAmount();
    // Requirement 2.0 section 2: in the farming module **only the first order (pid=0) participates in the redemption mechanism**, and **the first-order entitlement is permanently exhausted**.
    //   -- Each address gets only one redemption opportunity in its lifetime; whether the first order is closed by active redemption or by 3x max-out,
    //      the entitlement never regenerates, and all subsequently rebuilt orders (pid>=1) are never redeemable. This is a hard constraint of the economic model.
    // Pitfall: do not rely on Position.flags -- that flag is only set when "redeemable amount = 0",
    //       which would let rebuilt orders silently become redeemable while yield has not exceeded 50% of principal, conflicting with "permanently exhausted".
    if (!_isFirstPosition(positionId)) revert CoreVault_NotFirstPosition(positionId);
    Position storage p = fv.positions[positionId];
    if (p.flags & 1 != 0) revert CoreVault_InvalidAmount();
    if (p.flags & 2 != 0) revert CoreVault_InvalidAmount();
    if (block.timestamp < p.depositTime + GlobalConfig.LOCKUP_MIN) revert CoreVault_InvalidAmount();
    uint256 pendingUsd = _pendingYield(p);
    if (pendingUsd > 0) {
      _processYieldPayout(user, positionId, fv, p, pendingUsd);
      if (p.flags & 1 != 0) return;
    }
    p.lastRewardTime = block.timestamp;
    uint256 totalEarnedUsd;
    unchecked {
      totalEarnedUsd = p.earnedUsd
        + (fv.earnedDirect - p.snapshotDirect) + (fv.earnedTeam - p.snapshotTeam);
      if (totalEarnedUsd >= p.principalUsd * GlobalConfig.MAX_MULTIPLIER || p.earnedUsd >= p.principalUsd) {
        p.flags |= 1; _markExited(user);
        emit PositionClosed(user, positionId, 2);
        return;
      }
    }
    uint256 redeemableUsd = YieldMath.redeemablePrincipal(p.principalUsd, totalEarnedUsd);
    if (redeemableUsd == 0) { p.flags |= 2; return; }
    p.flags |= 1;
    p.redeemableUsd = redeemableUsd;
    (,, uint256 wbnbPerUsd) = OracleLib.getAccountingPrices(_oracle);
    if (wbnbPerUsd == 0) revert CoreVault_PriceUnavailable();
    uint256 bnbAmount = Math.mulDiv(redeemableUsd, wbnbPerUsd, 1e18, Math.Rounding.Floor);
    treasury.payoutBnb(user, bnbAmount);
    emit PrincipalRedeemed(user, positionId, redeemableUsd);
  }
}

Contracts/CoreVaultStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {OracleLib} from "../src/core/OracleLib.sol";
import {GlobalConfig} from "../src/core/GlobalConfig.sol";
import {CoreVaultReferral} from "./CoreVaultReferral.sol";

/// @title  CoreVaultStaking -- staking core logic
/// @notice stakeA/stakeB entry points, staking cycle management, yield calculation, unlock, fuel fee injection, donation.
/// @dev 3rd generation (facet split version) rewritten version -- for evidence and limitations see the top note of CoreVaultStorage.sol.
///      WARNING: key difference from the 2nd generation: **all staking view functions have been moved out** to
///      `src/core/CoreVaultViewFacet.sol`. Reason (compile-time hard constraint): `src/CoreVault.sol` keeps a **same-named wrapper**
///      for every moved function (`activeOrder` / `getModValues` / `getTotalPoolA` ...);
///      if this layer still kept a same-named `external` function, it would be a **duplicate definition** and fail to compile.
///      So this file keeps only "state-change logic" and declares no views at all.
abstract contract CoreVaultStaking is CoreVaultReferral {
  using SafeERC20 for IERC20;

  // ════════════════════════════════════════════════════════════
  //  Staking core
  // ════════════════════════════════════════════════════════════

  function _stakeCore(address user, uint256 amount, address referrer, TokenType t) internal {
    StakeState storage s = (t == TokenType.A) ? _aStakes[user] : _bStakes[user];
    if (t == TokenType.A) {
      if (amount < GlobalConfig.MIN_STAKE_A || amount > GlobalConfig.MAX_STAKE_A) revert CoreVault_InvalidAmount();
    } else {
      if (amount < GlobalConfig.MIN_STAKE_B || amount > GlobalConfig.MAX_STAKE_B) revert CoreVault_InvalidAmount();
    }
    bool hasActive = (s.active.flags & 1) != 0;
    if (hasActive) {
      if (block.timestamp < s.active.endTime) revert CoreVault_InvalidAmount();
      if (amount < s.active.principal) revert CoreVault_InvalidAmount();
    }
    (uint256 spotARate, uint256 spotBRate,) = OracleLib.getAllPrices(_oracle);
    (uint256 avgARate, uint256 avgBRate,) = OracleLib.getAccountingPrices(_oracle);
    if (spotARate == 0 || spotBRate == 0) revert CoreVault_PriceUnavailable();
    _register(user, referrer);
    // Requirement 2.0: rebuilding a new order in this pool restores **this pool's** dynamic yield entitlement and zeroes this pool's dynamic yield accumulation.
    // Pitfall: without zeroing, the leftover 3x dynamic yield would immediately trigger another max-out on the next distribution, and the user could not truly restore entitlements.
    // Pitfall (severe): only touch this pool's (t) entitlement bit and accumulation -- the other pool's orders/entitlements/accumulation are completely unaffected
    //   (OSK and FIST staking performance are independent, and max-out in one does not implicate the other).
    if (_stakingRightsClosed(user, t)) {
      // Design doc section 7.3 "order-stacking rule": rebuilding after max-out requires the new order amount to be **>= the principal of the last order before max-out**.
      //   Evidence: design doc section 7.3 "rebuild after max-out: check amount >= s.lastPrincipal (not cleared by delete,
      //         retains the principal of the last order before max-out)".
      // Pitfall: this check must be **before clearing the entitlement bit** -- use `_stakingRightsClosed` to judge "whether in a maxed-out state".
      // Pitfall: use `s.lastPrincipal`, not `s.active.principal` -- active has already been deleted at max-out.
      if (amount < s.lastPrincipal) revert CoreVault_InvalidAmount();
      _refs[user].flags &= ~_stakeRightsBit(t);
      _modEarnedDirectByPool[user][t] = 0;
      _modEarnedTeamByPool[user][t] = 0;
      emit StakingRightsRestored(user, t);
    }
    uint256 perfRate = (t == TokenType.A) ? avgARate : avgBRate;
    if (perfRate == 0) revert CoreVault_PriceUnavailable();
    unchecked {
      uint256 usdVal = Math.mulDiv(amount, 1e18, perfRate, Math.Rounding.Floor);
      if (t == TokenType.A) _totalPoolA += usdVal; else _totalPoolB += usdVal;
      _updateTeamPerf(user, usdVal, t);
    }
    bool hasReady = false;
    if (hasActive) {
      if ((s.ready.flags & 1) != 0) _unlockReady(user, s, t);
      s.ready = s.active; s.active.flags = 0; hasReady = true;
    }
    s.active = Order({principal: amount, startTime: block.timestamp, endTime: block.timestamp + GlobalConfig.CYCLE, flags: 1});
    // Design doc section 7.3: record this order's principal as the amount baseline for **the next rebuild after max-out**.
    //   Updated on every successful order creation (including full-cycle rebuilds), so the baseline moves forward with the latest order.
    s.lastPrincipal = amount;
    emit Staked(user, amount, block.timestamp + GlobalConfig.CYCLE, t);
    if (hasReady) _unlockReady(user, s, t);
    // Requirement 2.0: static yield deferred at max-out is paid out to the user when a **new position is rebuilt**.
    // Pitfall: must come after all state changes (CEI) -- it contains an external token transfer internally.
    // Pitfall: pay per pool -- only this pool's (t) deferred value is paid; the other pool's deferred value is unaffected.
    _payPendingStaticYield(user, s, t);
  }

  /// @dev Pay out static yield deferred at max-out
  /// @notice Called only when a **new position is rebuilt** in this pool (Requirement 2.0: static yield is triggered to the user on creating a new position).
  /// Pitfall: zero first, then transfer (CEI) -- prevents reentrancy-caused duplicate payouts.
  /// Pitfall: on insufficient balance **revert explicitly** rather than silently skipping -- the user's static yield must not be lost;
  ///       better to fail this stake and expose the reserve problem than to silently swallow user assets.
  function _payPendingStaticYield(address user, StakeState storage s, TokenType t) internal {
    uint256 pending = s.pendingStaticYield;
    if (pending == 0) return;
    s.pendingStaticYield = 0;
    _payoutStaking(user, pending, t);
    emit StakingYieldPaid(user, t, pending);
  }

  function _calcReward(uint256 principal, uint256 end) private view returns (uint256) {
    // Per-cycle yield = principal × 7% (requirements doc: daily yield 0.7% × 10 days/cycle)
    // [Confirmed] Staking is per-cycle and accrues no interest beyond the cycle: returns 0 before a full cycle; after a full cycle the yield is always 7%,
    //           not accrued per day for overtime, and no compounding. Not reading elapsed here is the implementation guarantee of that rule.
    // Pitfall: the denominator is uniformly RATE_PRECISION (1e4), bit-for-bit equivalent to the old implementation mulDiv(p,7000,100000).
    // Pitfall: delegate uniformly to the shared base _orderStaticYield -- max-out deferral and unlock settlement must use the same policy,
    //       otherwise the deferred value could differ from the settlement value (policy divergence).
    return _orderStaticYield(principal, end);
  }

  function _unlockReady(address user, StakeState storage s, TokenType t) internal {
    Order memory r = s.ready;
    if (block.timestamp < r.endTime) revert CoreVault_InvalidAmount();
    uint256 reward = _calcReward(r.principal, r.endTime);
    uint256 total = r.principal + reward;
    s.totalEarned += reward;
    (uint256 avgARate, uint256 avgBRate,) = OracleLib.getAccountingPrices(_oracle);
    unchecked {
      uint256 poolUsd = Math.mulDiv(r.principal, 1e18,
        t == TokenType.A ? avgARate : avgBRate, Math.Rounding.Floor);
      if (t == TokenType.A) {
        if (poolUsd < _totalPoolA) _totalPoolA -= poolUsd; else _totalPoolA = 0;
      } else {
        if (poolUsd < _totalPoolB) _totalPoolB -= poolUsd; else _totalPoolB = 0;
      }
    }
    delete s.ready;
    emit Unlocked(user, r.principal, reward, t);
    _payoutStaking(user, total, t);
    if (reward > 0) _distributeStakingRewards(user, reward, t);
  }

  // ════════════════════════════════════════════════════════════
  //  Staking external entry points
  // ════════════════════════════════════════════════════════════

  /// @notice OSK staking (Requirement 2.0 section 4)
  /// @dev Fuel fee policy (Requirement 2.0 section 4, staking rule 2 "2% of the staking amount in FIST is injected into the FIST staking mining pool"):
  ///      charged at 2% in the **opposite token** (FIST) by USD equivalent, and **deducted additionally from the user's wallet** -- the staking principal is untouched.
  ///      Destination: FIST is injected into the FIST staking mining pool on receipt (this contract's bToken balance is that pool's redemption reserve).
  ///      Word-for-word consistent with sections 7.1/7.2 of the design doc `docs/02-design/fund-flow-and-implementation-details.md`.
  /// Pitfall: a farming position must already exist to count as **having locked the relationship through farming**; checking only the referrer cannot stop the first user from staking directly.
  ///       The gate is placed before transferFrom to avoid invalid approvals and transfers (Requirement 2.0 section 5).
  /// Pitfall: the principal (OSK) and the fuel (FIST) are **two different tokens**, so two transferFrom calls are needed and the user must approve each separately --
  ///       they cannot be merged into one (the old implementation merged them as the same token, the opposite of the requirement policy).
  function stakeA(uint256 amount) external {
    _guardEnter();
    if (_fvUsers[msg.sender].positions.length == 0) revert CoreVault_NoReferrer();
    _requireValidReferrer(_refs[msg.sender].referrer);
    if (amount < GlobalConfig.MIN_STAKE_A || amount > GlobalConfig.MAX_STAKE_A) revert CoreVault_InvalidAmount();
    uint256 fee = _stakeFeeInOpposite(amount); // charged in FIST
    IERC20(address(aToken)).safeTransferFrom(msg.sender, address(this), amount);
    IERC20(address(bToken)).safeTransferFrom(msg.sender, address(this), fee);
    // CEI: settle all staking state and reward distribution first, then do the fuel fee injection's external interaction
    _stakeCore(msg.sender, amount, _refs[msg.sender].referrer, TokenType.A);
    _injectStakeFeeToFistPool(msg.sender, fee);
    _guardExit();
  }

  /// @notice FIST staking (Requirement 2.0 section 3)
  /// @dev Fuel fee policy (**client change on 2026-09-26**): charged at 2% in the **staking token itself** (FIST),
  ///      deducted additionally from the user's wallet -- the staking principal is untouched (staking 100 FIST deducts another 2 FIST).
  ///      Destination: transfer to treasury -> half of the FIST is swapped to OSK -> remaining FIST + obtained OSK form OSK/FIST LP -> insurance pool.
  ///      Policy **differs** from stakeA: stakeA is still charged in the opposite token (FIST), while stakeB is charged in the same token,
  ///      so stakeB **needs no oracle conversion** (pure token count × 2%).
  /// Pitfall: same gate as stakeA -- validate the referral relationship before pulling funds.
  /// Pitfall: principal and fuel are both FIST, merged into a single transferFrom(amount + fee) -- no need for two approvals/two transfers.
  function stakeB(uint256 amount) external {
    _guardEnter();
    if (_fvUsers[msg.sender].positions.length == 0) revert CoreVault_NoReferrer();
    _requireValidReferrer(_refs[msg.sender].referrer);
    if (amount < GlobalConfig.MIN_STAKE_B || amount > GlobalConfig.MAX_STAKE_B) revert CoreVault_InvalidAmount();
    uint256 fee = _stakeFeeSame(amount); // charged at 2% in FIST
    IERC20(address(bToken)).safeTransferFrom(msg.sender, address(this), amount + fee);
    // CEI: settle all staking state and reward distribution first, then do the fuel fee injection's external interaction
    _stakeCore(msg.sender, amount, _refs[msg.sender].referrer, TokenType.B);
    _injectStakeFeeToOskLp(msg.sender, fee);
    _guardExit();
  }

  /// @dev Client change on 2026-09-26: the FIST staking fuel fee is changed to be charged at 2% in the **same token** (FIST).
  ///      Policy: fee = amount × STAKE_FEE_BP / RATE_PRECISION (pure token count, no oracle conversion).
  /// Pitfall: do not go through `_stakeFeeInOpposite` again -- that would charge in the opposite token (OSK), the opposite of the changed policy;
  ///       when OSK is very cheap, that opposite-token fuel fee balloons to thousands of times the principal (measured ~3093 OSK / 1 FIST).
  function _stakeFeeSame(uint256 amount) internal pure returns (uint256) {
    return Math.mulDiv(amount, GlobalConfig.STAKE_FEE_BP, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
  }

  /// @dev Requirement 2.0 section 4, staking rule 2: the fuel fee for OSK(A) staking = 2% of the staking amount, charged in the **opposite token** (FIST).
  ///      Conversion policy (USD equivalent, same source as `_stakeCore`'s performance pricing, see design doc section 7.2):
  ///        stakeA(OSK) -> FIST : fee = amount × STAKE_FEE_BP/1e4 × avgBRate / avgARate
  ///      where avgARate = how many OSK per 1 USD, avgBRate = how many FIST per 1 USD.
  ///      Derivation: amount / avgRate = USD value; × 2% = fuel USD; × opposite avgRate = opposite token count.
  /// Note: only stakeA uses this function; stakeB was changed on 2026-09-26 to charge in the same token (see `_stakeFeeSame`).
  /// Pitfall: a **unit/dimension conversion** is required rather than using amount directly -- the requirement prices in the opposite token, and OSK has 18 decimals
  ///       while FIST has 6, so the two cannot be mixed (using it directly would make the fuel fee off by 1e12 times).
  /// Pitfall: when either price is 0, **revert explicitly** -- never treat 0 as a price, otherwise it would silently compute a 0 fuel fee and undercharge.
  function _stakeFeeInOpposite(uint256 amount) internal returns (uint256 fee) {
    (uint256 avgARate, uint256 avgBRate,) = OracleLib.getAccountingPrices(_oracle);
    if (avgARate == 0 || avgBRate == 0) revert CoreVault_PriceUnavailable();
    uint256 feeSame = Math.mulDiv(amount, GlobalConfig.STAKE_FEE_BP, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
    fee = Math.mulDiv(feeSame, avgBRate, avgARate, Math.Rounding.Floor);
  }

  // ════════════════════════════════════════════════════════════
  //  Requirement 2.0 sections 3/4, mining pool source (1): donation from any external address
  // ════════════════════════════════════════════════════════════

  /// @notice Any address injects OSK into the **OSK staking mining pool** (Requirement 2.0 section 4, mining pool source (1))
  /// @dev Requirement text: "mining pool source: 1; any external address may inject OSK".
  /// Design intent: **no permission gate** -- any address may call it, and the donation goes directly into this contract's balance,
  ///           strengthening the redemption capacity of OSK staking rewards. It is not a privilege: the caller can only **give up** assets and has no withdrawal capability.
  /// Pitfall: measure by "balance delta" rather than trusting the input parameter -- if the token charges a transfer tax, the input would exceed the actual received amount,
  ///       and adding it directly would overstate _totalDonatedA and distort the audit data (same idea as Treasury's baseline sweep).
  /// Pitfall: not counted into _totalPoolA -- the latter means "unsettled principal pool (USD denominated)", while a donation is an extra redemption reserve,
  ///       and mixing it in would overstate the pool accounting. See the storage comments in CoreVaultStorage.
  function donateOskPool(uint256 amount) external {
    _guardEnter();
    if (amount == 0) revert CoreVault_InvalidAmount();
    _donateCore(msg.sender, amount, TokenType.A);
    _guardExit();
  }

  /// @notice Any address injects FIST into the **FIST staking mining pool** (Requirement 2.0 section 3, mining pool source (1))
  /// @dev Requirement text: "mining pool source: 1; any external address may inject FIST". Semantics are symmetric to donateOskPool.
  function donateFistPool(uint256 amount) external {
    _guardEnter();
    if (amount == 0) revert CoreVault_InvalidAmount();
    _donateCore(msg.sender, amount, TokenType.B);
    _guardExit();
  }

  /// @dev Shared donation pipeline: pull tokens -> record by balance delta -> emit event
  /// Pitfall: doing transferFrom before state changes is **intentional** -- the delta can only be measured after the transfer;
  ///       if transferFrom fails the whole call reverts, state included, so there is no half-completed state.
  /// Pitfall: revert explicitly when received == 0 -- prevents a misleading event of "claiming a donation but receiving zero".
  function _donateCore(address donor, uint256 amount, TokenType t) internal {
    IERC20 token = (t == TokenType.A) ? IERC20(address(aToken)) : IERC20(address(bToken));
    uint256 balBefore = token.balanceOf(address(this));
    token.safeTransferFrom(donor, address(this), amount);
    uint256 received = token.balanceOf(address(this)) - balBefore;
    if (received == 0) revert CoreVault_InvalidAmount();
    unchecked {
      if (t == TokenType.A) _totalDonatedA += received;
      else _totalDonatedB += received;
    }
    emit PoolDonated(donor, t, received);
  }

  // ════════════════════════════════════════════════════════════
  //  Requirement 2.0 sections 3/4, staking rule 2: destination of the 2% staking fuel fee (opposite token)
  // ════════════════════════════════════════════════════════════

  /// @dev Fuel fee (FIST) of **stakeA (OSK staking)** -> **FIST staking mining pool**
  /// Requirement 2.0 section 4, rule 2 text: "2% of the staking amount in FIST is injected into the FIST staking mining pool".
  /// Design intent: the FIST staking mining pool's redemption reserve **is exactly this contract's bToken balance** -- staking principal and rewards are both redeemed from that balance,
  ///           so the fuel fee is **already injected on receipt**, requiring no swap or transfer. Only an event is emitted here for audit cross-checking.
  /// Pitfall: **do not** transfer it to the Treasury to swap into FIST -- the fuel is already FIST, and an extra swap would only waste
  ///       0.25% fee plus slippage, and violate the literal policy of "inject into the FIST staking mining pool".
  function _injectStakeFeeToFistPool(address user, uint256 fee) internal {
    if (fee == 0) return;
    emit StakeFeeInjected(user, fee, TokenType.B, true);
  }

  /// @dev Fuel fee (FIST) of **stakeB (FIST staking)** -> **OSK LP base pool**
  /// Client change on 2026-09-26: the fuel fee is charged in the **staking token itself** (FIST), and the destination is still OSK/FIST LP.
  /// Design intent: swapping and LP formation are centralized in the treasury layer (CoreVault holds no router dependency);
  ///           `Treasury.injectFistToOskLp` is exactly that policy -- split in half -> half the FIST is swapped to OSK
  ///           -> remaining FIST + obtained OSK form OSK/FIST LP -> insurance pool.
  /// Pitfall: when not wired or the LP path fails, the whole call must revert. The user must not be allowed to complete FIST staking
  ///       while the fuel fee stays in CoreVault/Treasury without forming LP.
  function _injectStakeFeeToOskLp(address user, uint256 fee) internal {
    if (fee == 0) return;
    address t = address(treasury);
    if (t.code.length == 0) revert CoreVault_ZeroAddress();
    IERC20(address(bToken)).safeTransfer(t, fee);
    treasury.injectFistToOskLp(fee, GlobalConfig.LP_SLIPPAGE_BP);
    emit StakeFeeInjected(user, fee, TokenType.B, true);
  }

  // ════════════════════════════════════════════════════════════
  //  WARNING: 3rd generation: this layer's former "staking view functions" section has been **moved out entirely** to
  //     `src/core/CoreVaultViewFacet.sol` (activeOrder / getModValues /
  //     totalEarnedAllStaking / getTotalPoolA / getTotalPoolB / getTotalDonated /
  //     getPoolReserve / isStakingRightsClosed / getStakingDynamicEarned /
  //     getPendingStaticYield / getStakingMaxOutProgress / getThreeSectorStatus).
  //     The reason for the move and the hard constraint are in this file's top @dev.
  // ════════════════════════════════════════════════════════════
}

Contracts/CoreVaultStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IAToken} from "../src/interfaces/IAToken.sol";
import {IBToken} from "../src/interfaces/IBToken.sol";
import {YieldMath} from "../src/lib/YieldMath.sol";
import {IPancakePair} from "../src/interfaces/IPancake.sol";
import {Treasury} from "../src/core/Treasury.sol";
import {OracleLib} from "../src/core/OracleLib.sol";
import {GlobalConfig} from "../src/core/GlobalConfig.sol";
import {Auth} from "../src/access/Auth.sol";
import {TransientReentrancyGuard} from "../src/access/TransientReentrancyGuard.sol";

/// @title  CoreVaultStorage -- storage base class
/// @notice All state variables, structs, events and custom errors are defined here. The private->internal migration only affects compile-time visibility, not storage slot allocation.
/// @dev Inheriting Auth+TransientReentrancyGuard makes onlyOwner/_guardEnter/_guardExit available across the whole refactor chain.
///
/// @dev ===== WARNING: this file is the "3rd generation" rewritten version, please read carefully =====
/// Provenance: this repo's `Contracts/` is entirely missing for the 3rd generation (facet split version). It is rewritten here from the following **verifiable evidence**:
///   (1) the intermediate generation (2nd generation) version -- **byte-for-byte reconstructed** from the upstream base version `D:\code\cgbb1\code` + `archive/cgbb1_diff.txt`
///      via `git apply` (blob 11/11 match). See `_recovered/lineage-and-generations.md`.
///   (2) the **function selector set** of the on-chain 2026-09-21 mainnet test deployment (`0xf540c915...`) --
///      used to determine which external functions truly exist/do not exist in the 3rd generation (e.g. `swapEngine()` does not exist).
///   (3) the **actual references** of `src/CoreVault.sol` / `src/core/CoreVaultViewFacet.sol` to this contract.
///   (4) the change list in `docs/03-deploy/mainnet-test-deployment-guide.md`.
/// WARNING: therefore this file is **not** a verbatim copy of the original 3rd generation source, but a "reconstruction under evidence constraints".
///    The real 3rd generation source must still be retrieved from an external source before it can serve as an audit baseline.
abstract contract CoreVaultStorage is Auth, TransientReentrancyGuard {
  using SafeERC20 for IERC20;

  enum TokenType { A, B }

  // ════════════════════════════════════════════════════════════
  //  3rd generation change 1: the three main dependencies changed from immutable to **storage**
  // ════════════════════════════════════════════════════════════
  // Reason (hard constraint): facets are called via **DELEGATECALL**, while immutable values are compiled into **code**
  //   and do not exist in storage. If kept immutable, CoreVaultViewFacet / CoreVaultLogicFacet would read
  //   **their own** immutable values (unconstructed -> all 0), not CoreVault's real dependencies.
  // On-chain confirmation: the 9/21 deployment has the three public getters `aToken()` / `bToken()` / `treasury()`.
  // WARNING: storage layout: the three go from "not occupying a slot" to "occupying slots 0/1/2", shifting all subsequent variable slot numbers.
  //   This contract is **non-upgradeable** and the 3rd generation was redeployed anyway, so there is no migration issue;
  //   and since the 3rd generation already changed `getFarmingRaw` from "hard-coded slot 45" to **reading the mapping directly**
  //   (see src/core/CoreVaultViewFacet.sol), the shifted slot numbers no longer cause a mismatch.
  IAToken   public aToken;
  IBToken   public bToken;
  Treasury  public treasury;

  OracleLib.OracleState internal _oracle;

  struct RefInfo {
    address referrer;
    uint8   teamLevel;
    uint8   validDirectCount;
    // flags bit definitions (Requirement 2.0):
    //   bit0 (1) = registered
    //   bit1 (2) = first valid deposit completed (_markFirstInvest)
    //   bit2 (4) = **OSK(A) staking** dynamic yield entitlement closed -- set after this pool's dynamic yield reaches 3x principal and maxes out,
    //              and only rebuilding a new order in this pool (staking A again) clears it and restores the entitlement.
    //   bit3 (8) = **FIST(B) staking** dynamic yield entitlement closed -- same as above, independent of bit2.
    // Pitfall: OSK and FIST staking are two independent mechanisms (performance computed independently, max-out does not affect the other), so each has its own flag bit.
    //       If the two pools shared one bit, an OSK pool max-out would also close the FIST pool entitlement -- a cross-module unauthorized closure.
    uint8   flags;
  }
  mapping(address => RefInfo) internal _refs;
  mapping(address => address[]) internal _directReferrals;

  struct Order {
    uint256 principal;
    uint256 startTime;
    uint256 endTime;
    uint8   flags;
  }
  struct StakeState {
    Order   active;
    Order   ready;
    uint256 totalEarned;
    // Requirement 2.0: **static yield** deferred at 3x max-out.
    //   Max-out rule: orders are closed + principal is not refunded, but this pool's already-generated static yield **must not be destroyed**;
    //   it is deferred here, to be paid out to the user in one go when they **rebuild a new position in this pool**.
    // Pitfall (severe): do not delete it along with the orders at max-out -- that would destroy the user's already-generated static yield,
    //   violating "static yield is triggered to the user when a new position is created".
    // Pitfall: per-pool independent -- pool A's deferred value must not affect pool B.
    // WARNING: storage layout: StakeState sits in a mapping value position, so new fields do not occupy additional top-level slots
    //   (_aStakes/_bStakes each always occupy 1 slot), thus not affecting other state variables' slots; but the struct layout inside existing mapping entries
    //   does change, requiring a full redeployment (this contract was non-upgradeable anyway).
      uint256 pendingStaticYield;
      // Design doc section 7.3 "order-stacking rule": on rebuilding after max-out, the new order amount must be **>= the principal of the last order before max-out**.
      //   This field is that baseline (active is deleted at max-out, so it must be retained separately).
      // Pitfall: do not use `s.active.principal` instead -- at max-out active is zeroed along with the deleted orders.
      // Pitfall: update it on every successful order creation (including full-cycle rebuilds), so the baseline moves forward with the latest order.
      uint256 lastPrincipal;
    }
  mapping(address => StakeState) internal _aStakes;
  mapping(address => StakeState) internal _bStakes;

  uint256 internal _totalPoolA;
  uint256 internal _totalPoolB;

  struct ModValues {
    uint256 teamUsd;
    uint256 directUsd;
    uint256 maxUsd;
  }
  mapping(address => ModValues) internal _modA;
  mapping(address => ModValues) internal _modB;

  mapping(address => uint256) internal _modEarnedDirect;
  mapping(address => uint256) internal _modEarnedTeam;

  bool internal _hasUsers;

  struct Position {
    uint256 principalUsd;
    uint256 principalA;
    uint256 earnedYield;
    uint256 earnedUsd;
    uint256 lastRewardTime;
    uint256 depositTime;
    uint8   flags;
    uint256 redeemableUsd;
    uint256 snapshotDirect;
    uint256 snapshotTeam;
    // Requirement 2.0 section 2: deposit token flag -- 0 = BNB, 1 = FIST.
    // Design intent: one farming mechanism supports both BNB and FIST deposits; the two channels share the same yield/3x max-out/redemption formulas,
    //           differing only in "deposit token" and "fund allocation path", so a single flag field suffices to distinguish them.
    // Pitfall: redemption is always settled in BNB (Requirement 2.0 section 2: "regardless of whether farming used bnb or fist, redemption is always settled to the user in BNB"),
    //       so this field does not participate in redemption amount computation and is only for indexing/audit and frontend display differentiation.
    // WARNING: storage layout warning (measured): this field changes the Position element stride from 10 slots -> 11 slots.
    //   Consequence: the address of _fvUsers[u].positions[i] differs from the old layout (i × 10),
    //        so **every array element of existing on-chain positions would be read misaligned**, with principal/yield/snapshot fields all shifted.
    //   Conclusion: this change **requires a full redeployment of CoreVault**; in-place upgrade on a deployed instance is forbidden (this contract is non-upgradeable, no Proxy).
    //   Pitfall: if Position needs to be extended again in the future, first change it to "append at the end + reserve a gap" or use a separate mapping,
    //        to avoid shifting the whole array again.
    uint8   depositToken;
  }
  struct FvUser {
    Position[] positions;
    uint256 totalInvestedUsd;
    uint256 totalEarned;
    uint256 totalTeamUsd;
    uint256 totalDirectUsd;
    uint256 earnedDirect;
    uint256 earnedTeam;
    uint256 pendingDirect;
    uint256 pendingTeam;
    uint8   flags;
    uint256 maxUsd;
  }
  mapping(address => FvUser) internal _fvUsers;

  uint256[] internal _tierUppers;
  uint256[] internal _teamThresholds;

  address public feewallet1;
  address public bPool;
  address public aPool;

  uint256 public totalAPoolRewards;
  uint256 public totalBPoolRewards;

  // ════════════════════════════════════════════════════════════
  //  3rd generation change 2: removed `address public swapEngine;`
  // ════════════════════════════════════════════════════════════
  // Evidence: the on-chain 9/21 deployment **does not have** the `swapEngine()` selector (f183cf14 miss),
  //   and `setSwapEngine(address)` (60f3b696) also misses => the 3rd generation fully removed this variable and setter.
  //   In the 2nd generation it was used only by the "deprecated withdrawal-tax -> swapEngine distribution" path, which has moved to
  //   `treasury.swapOskToFistAndInject`, so there is no dangling reference after removal.

  // ════════════════════════════════════════════════════════════
  //  Requirement 2.0 sections 3/4, 3x max-out: per-pool dynamic yield accounting (new storage)
  // ════════════════════════════════════════════════════════════
  // Pitfall (severe): dynamic yield must be measured **separately per pool** -- if the cross-pool aggregate values _modEarnedDirect/_modEarnedTeam
  //   were used in the max-out determination, dynamic yield generated by pool A would also mark pool B's orders as maxed out
  //   (double confiscation of principal), an irreversible fund error.
  //   Note: _modEarnedDirect/_modEarnedTeam remain as cross-pool aggregates, used only for view/audit display, not in the max-out determination.
  mapping(address => mapping(TokenType => uint256)) internal _modEarnedDirectByPool;
  mapping(address => mapping(TokenType => uint256)) internal _modEarnedTeamByPool;

  // ════════════════════════════════════════════════════════════
  //  Requirement 2.0 sections 3/4, mining pool source (1): donation from any external address (new storage)
  // ════════════════════════════════════════════════════════════
  // Design intent: the requirement "any external address may inject FIST / inject OSK" --
  //   a donation directly increases this contract's token balance, thereby strengthening that pool's reward redemption capacity.
  // Pitfall: donations are **not counted into** _totalPoolA/_totalPoolB -- the latter means "unsettled principal pool (USD denominated)",
  //   while a donation is an extra redemption reserve rather than principal; mixing it in would overstate pool accounting and distort semantics.
  uint256 internal _totalDonatedA; // cumulative OSK donated to the pool (measured in the original token)
  uint256 internal _totalDonatedB; // cumulative FIST donated to the pool (measured in the original token)

  // ════════════════════════════════════════════════════════════
  //  3rd generation change 3: insurance pool address + farming deposit bounds (appended storage)
  // ════════════════════════════════════════════════════════════
  // Evidence: the "change list" section of docs/03-deploy/mainnet-test-deployment-guide.md explicitly records
  //   - `Contracts/CoreVaultStorage.sol` added the `DepositBoundsUpdated` event
  //   - `Contracts/CoreVaultAdmin.sol` added the `setDepositBounds()` + `depositBounds()` views
  //   - 4 new variables **appended after all existing state variables** (after _totalDonatedB), not shifting existing slots
  // On-chain confirmation: `insurancePool()` (ab2adc00) / `depositBounds()` (562705dc) /
  //   `setDepositBounds(uint256,uint256,uint256,uint256)` (92736b07) all hit.
  // Design intent: production takes the GlobalConfig production values by default; the mainnet test build has owner call setDepositBounds
  //   to override them with small bounds (e.g. 0.001 BNB / 1 USD), enabling small end-to-end verification on the real chain.
  // Pitfall: use storage rather than constant -- otherwise the test build and the production build must be compiled and deployed separately, unable to share bytecode.
  address public insurancePool;

  uint256 internal _minDepositBnb;
  uint256 internal _maxDepositBnb;
  uint256 internal _minDepositUsd;
  uint256 internal _maxDepositUsd;

  // ════════════════════════════════════════════════════════════
  //  Node mining pool 30% dividend wiring (appended storage)
  // ════════════════════════════════════════════════════════════
  // Source: `node-requirements-doc.txt` section 1, entitlements -- "5%/5%/10%/10% of network-wide static revenue is injected into the node mining pool and split equally",
  //   totaling 30% of static revenue -> four-pool weighting (founder 5 / co-founder 5 / sponsor 10 / operation 10, sum = 30).
  // Policy (1.0, confirmed): farming **gross expense** = user 100% + referral 20% + team 50% + node 30% = 200%
  //   (all **pre-tax**). That is, the node leg is an **additional** expense, not deducted from the user's share.
  //   -> implemented in `Contracts/CoreVaultFarming.sol::_processYieldPayout`.
  // Difference from the withdrawal-tax route (two **independent** node dividends):
  //   - this variable (30% static revenue) -> `NodePoolDistributor` -> A/B/E/D **weighted 5/5/10/10**;
  //   - `feewallet1` (2.5% withdrawal tax) -> `BWalletDistributor5` -> A/B/C/D/E **split equally 5 ways**.
  //   Both are denominated in OSK, but their sources and allocation methods differ and must not be mixed up.
  // On-chain confirmation: the 9/21 deployment has the two selectors `nodePoolDistributor()` (b691b3ee) /
  //   `setNodePoolDistributor(address)` (3b00b729) -- this variable and
  //   `CoreVaultAdmin::setNodePoolDistributor` are exactly their restoration (see Contracts/README.md section 3.3).
  // WARNING: storage layout: appended **after all existing state variables** (after `_maxDepositUsd`), not shifting existing slots.
  //   Same convention as the `insurancePool` block. This contract is non-upgradeable, and the 3rd generation was redeployed anyway.
  // Pitfall: when not wired (address(0)) the node leg is **silently skipped** -- same policy as `feewallet1`;
  //   it must never revert, otherwise a single unconfigured external address would block yield claiming for all users.
  address public nodePoolDistributor;

  // ════════════════════════════════════════════════════════════
  //  Staking dynamic yield "valid stake" gating (added 2026-09-26)
  // ════════════════════════════════════════════════════════════
  // Requirement: an upline must have a **valid stake** in this pool to claim this pool's (OSK/FIST) dynamic yield --
  //   uplines who have not staked (farming only) / have maxed out (3x max-out clears orders) receive nothing, and their amount is **retained in this pool**
  //   to strengthen redemption capacity (no longer passed further up).
  // Design intent: two independent counters measuring, per pool, "rewards retained in this pool because the upline had no valid stake" --
  //   strictly distinguished from `_totalDonatedA/B` (external donations): the two have different sources and must not be merged.
  // Pitfall: this counter is **measured in the original token** (OSK 18 decimals / FIST 6 decimals, each its own precision), with no USD conversion --
  //   conversion would require reading the oracle, a state change, which cannot be done on a pure accounting path.
  // Pitfall: the retained amount does not enter `_totalPoolA/B` -- the latter means "unsettled principal pool (USD denominated)",
  //   and mixing it in would overstate pool accounting and distort semantics (same policy as _totalDonatedA/B).
  // WARNING: storage layout: appended after all existing state variables (after `nodePoolDistributor`), not shifting existing slots.
  uint256 internal _redirectedToPoolA;
  uint256 internal _redirectedToPoolB;

  event Staked(address indexed user, uint256 amount, uint256 endTime, TokenType t);
  event Unlocked(address indexed user, uint256 principal, uint256 reward, TokenType t);
  event DirectRewardAccrued(address indexed referrer, address indexed user, uint256 amount, uint8 gen);
  event TeamRewardAccrued(address indexed upline, address indexed user, uint256 amount, uint8 level);
  event TeamLevelUp(address indexed user, uint8 newLevel);
  event BnbDeposited(address indexed user, uint256 bnbAmount, uint256 usdAmount, uint256 positionId);
  // Requirement 2.0 section 2, "FIST on-chain mining mechanism 2": FIST deposit opens a position
  event FistDeposited(address indexed user, uint256 fistAmount, uint256 usdAmount, uint256 positionId);
  // Requirement 2.0 sections 3/4, staking rule 2: the 2% staking fuel fee (deducted additionally from the wallet) has been handled per destination.
  //   t = **the fuel fee's own token**: B (FIST, from OSK staking or FIST staking) -> transfer to treasury to form OSK/FIST LP -> insurance pool.
  //   WARNING: 2026-09-26 change: the FIST staking fuel fee changed from "opposite OSK" to "same-token FIST", so stakeB is also B.
  //       Currently only stakeA's FIST fuel **stays directly in this contract** = FIST staking mining pool reserve (bypassing the treasury).
  //   If fuel fee injection fails the whole stake reverts; a successful stake call only ever emits injected=true.
  event StakeFeeInjected(address indexed user, uint256 feeAmount, TokenType t, bool injected);
  // Requirement 2.0 sections 3/4, mining pool source (1): donation from any external address to the staking mining pool
  event PoolDonated(address indexed donor, TokenType t, uint256 amount);
  event YieldClaimed(address indexed user, uint256 positionId, uint256 amount);
  event PositionClosed(address indexed user, uint256 positionId, uint256 reason);
  event PrincipalRedeemed(address indexed user, uint256 positionId, uint256 amount);
  event ReferralRegistered(address indexed user, address indexed referrer);
  // Requirement 2.0 sections 3/4: a V1+ user's dynamic yield reaches 3x principal -> max-out closes orders, principal not refunded
  event StakingMaxOut(address indexed user, TokenType t, uint256 principal, uint256 dynamicEarned);
  // Requirement 2.0 sections 3/4: rebuilding a new order -> dynamic yield entitlement restored
  event StakingRightsRestored(address indexed user, TokenType t);
  // Requirement 2.0 sections 3/4: static yield deferred at max-out (paid when a new position is rebuilt)
  event StakingYieldDeferred(address indexed user, TokenType t, uint256 amount);
  // Requirement 2.0 sections 3/4: new position rebuilt -> deferred static yield paid out to the user
  event StakingYieldPaid(address indexed user, TokenType t, uint256 amount);
  // Staking dynamic yield "valid stake" gating: the upline has no valid stake in this pool -> the amount that would have gone to them is retained in this pool.
  //   kind: 0 = direct referral reward, 1 = team differential; amount is the **original-token** amount (gross before tax).
  event StakingRewardRedirected(address indexed upline, address indexed user, uint256 amount, TokenType t, uint8 kind);
  // 3rd generation: farming deposit bounds adjusted by owner (change trace, for auditing the bound differences between the test and production builds)
  event DepositBoundsUpdated(uint256 minBnb, uint256 maxBnb, uint256 minUsd, uint256 maxUsd);
  // Node mining pool 30% dividend target adjusted by owner (wiring trace; the companion event of on-chain setNodePoolDistributor)
  event NodePoolDistributorSet(address indexed nodePoolDistributor);
  // On yield claim, 30% of static revenue is transferred out to the node mining pool (additional expense, not part of 3x max-out accounting)
  //   usdAmount = accrual base (USD, pre-tax); oskAmount = actual OSK amount transferred out
  event NodePoolYieldPaid(address indexed nodePool, uint256 usdAmount, uint256 oskAmount);
  // Emergency withdrawal trace (onlyOwner). No token restriction, full-amount withdrawal allowed -- client-confirmed on 2026-09-25.
  event EmergencyWithdrawn(address indexed token, address indexed to, uint256 amount);

  error CoreVault_ZeroAddress();
  error CoreVault_ZeroPrice();
  error CoreVault_InvalidAmount();
  error CoreVault_PriceUnavailable();
  error CoreVault_Shortfall(uint256 n, uint256 a);
  error CoreVault_UnknownOp(uint8 op);
  error CoreVault_NoReferrer();
  error CoreVault_SelfReferral();
  error CoreVault_ActivePositionExists(uint256 activePosId);
  error CoreVault_NoActivePosition();
  // Requirement 2.0 section 2: in the farming module only the first order (pid=0) participates in the redemption mechanism; orders rebuilt after 3x max-out are not redeemable.
  error CoreVault_NotFirstPosition(uint256 positionId);

  // ── Pure data helper functions ──

  function isRegistered(address u) internal view returns (bool) { return _refs[u].flags & 1 != 0; }

  /// @dev Requirement 2.0: whether the staking dynamic yield entitlement is closed (set after 3x max-out)
  /// WARNING: must be judged **per pool** -- OSK staking and FIST staking are two independent mechanisms (performance computed independently),
  ///    and an OSK pool max-out must never also close the FIST pool entitlement. Each occupies its own flag bit.
  function _stakingRightsClosed(address u, TokenType t) internal view returns (bool) {
    return _refs[u].flags & _stakeRightsBit(t) != 0;
  }

  /// @dev Entitlement-closed flag bit: A(OSK) = bit2, B(FIST) = bit3
  ///      Pitfall: do not reuse the same bit -- reuse would let one pool's max-out contaminate the other (cross-module unauthorized closure).
  function _stakeRightsBit(TokenType t) internal pure returns (uint8) {
    return t == TokenType.A ? 4 : 8;
  }

  /// @dev This pool's total dynamic yield (direct referral reward + team differential), used only in the 3x max-out determination
  ///      Pitfall: must be read per pool -- a cross-pool total would let pool A's yield trigger pool B's max-out.
  function _dynamicEarnedByPool(address u, TokenType t) internal view returns (uint256) {
    return _modEarnedDirectByPool[u][t] + _modEarnedTeamByPool[u][t];
  }

  /// @dev Whether the user has a **valid stake** in this pool -- the precondition for claiming staking dynamic yield (direct referral/team).
  ///      Valid = this pool has an unsettled order (active or ready), i.e. the principal is still locked in this contract.
  /// Policy (client-confirmed on 2026-09-26):
  ///   - not staked (farming only)      -> false, may not claim this pool's dynamic yield;
  ///   - maxed out (3x max-out clears orders) -> false (orders have been deleted), may not claim;
  ///   - full cycle elapsed without restaking -> true -- the principal is still locked in the contract, which counts as a "valid stake";
  ///   - rebuilt a new position in this pool after max-out -> true -- rebuilding restores this pool's entitlement (see _stakeCore).
  /// Pitfall: must be judged **per pool** -- a valid stake in pool A must not make pool B's rewards claimable (the two pools' performance is independent and max-out is not intertwined).
  function _hasValidStake(address u, TokenType t) internal view returns (bool) {
    StakeState storage s = (t == TokenType.A) ? _aStakes[u] : _bStakes[u];
    return (s.active.flags & 1) != 0 || (s.ready.flags & 1) != 0;
  }

  /// @dev A single order's **static yield** (staking yield, Requirement 2.0 sections 3/4: 0.7% daily × 10 days/cycle = 7%/cycle)
  ///      Policy: returns 0 before a full cycle (per-cycle, no overtime accrual); after a full cycle it is always "principal × FIXED_RATE_BP".
  ///      Design intent: extracted into a shared base function -- max-out deferral (CoreVaultReferral) and unlock settlement (CoreVaultStaking)
  ///                must use the **same** yield formula, otherwise the deferred value and the settlement value would diverge.
  function _orderStaticYield(uint256 principal, uint256 endTime) internal view returns (uint256) {
    if (principal == 0 || block.timestamp < endTime) return 0;
    return Math.mulDiv(principal, GlobalConfig.FIXED_RATE_BP, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
  }

  /// @dev Node mining pool 30% dividend leg (system 2, "30% of network-wide static revenue") -- **farming and staking share the same implementation**.
  ///      Source: `node-requirements-doc.txt` section 1, entitlements "5%/5%/10%/10% of network-wide static revenue is injected into the node mining pool and split equally".
  ///      Policy (client-confirmed on 2026-09-23; extended to the staking module the same day):
  ///        - all three modules (farming / OSK staking / FIST staking) accrue static revenue;
  ///        - gross expense = user 100% + direct referral 20% + team 50% + node 30% = 200% (pre-tax);
  ///        - the node leg is an **additional** expense, not deducted from the user's share, and **does not participate** in 3x max-out accounting.
  ///      Design intent for extracting into a shared base function: the two modules must use the **same** accrual policy,
  ///        otherwise there would be a divergence of "farming 30% / staking X%".
  /// @param baseUsd  accrual base (USD denominated). For farming, pass this claim's **confirmed paid** pendingUsd (after 3x trimming);
  ///                 for staking, pass the USD equivalent of this static yield (OSK pool: reward×avgARate; FIST pool: reward×avgBRate).
  /// @param avgARate OSK's USD conversion rate (how many OSK per 1 USD).
  ///                 The node pool (`NodePoolDistributor`) is **single-token immutable = OSK**, so it is always paid out in OSK --
  ///                 the FIST staking pool's static yield must first be converted by value into OSK (see the call site in CoreVaultReferral).
  /// Pitfall: when not wired (address(0)) **silently skip**, never revert -- same policy as `feewallet1`;
  ///       a single unconfigured external address must not block yield claiming/unlocking for all users.
  /// Pitfall: the event records the **actual received amount**, not the requested amount -- `payoutReward` silently truncates when the treasury balance is insufficient.
  function _payoutNodePoolLeg(uint256 baseUsd, uint256 avgARate) internal {
    if (baseUsd == 0 || nodePoolDistributor == address(0) || avgARate == 0) return;
    uint256 nodePoolUsd = Math.mulDiv(baseUsd, GlobalConfig.NODE_POOL_BP, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
    if (nodePoolUsd == 0) return;
    uint256 nodePoolA = Math.mulDiv(nodePoolUsd, avgARate, 1e18, Math.Rounding.Floor);
    if (nodePoolA == 0) return;
    uint256 paid = treasury.payoutReward(nodePoolDistributor, nodePoolA);
    emit NodePoolYieldPaid(nodePoolDistributor, nodePoolUsd, paid);
  }

  /// @dev Requirement 2.0 section 2: **first-order redemption entitlement** determination in the farming module -- "only the first order (pid=0) participates in the redemption mechanism".
  /// @notice Rule (confirmed): **the first-order entitlement is permanently exhausted**.
  ///   Meaning: each address gets only one redemption opportunity in its lifetime. Whether the first order is closed by
  ///         (a) the user's **active redemption**, or
  ///         (b) a **3x max-out** (principal not refunded),
  ///         the entitlement is **never regenerated** -- all subsequently rebuilt orders (pid>=1) are never redeemable.
  /// Pitfall: do not change this to rely on Position.flags -- that flag is only set when "redeemable amount = 0",
  ///       which would let rebuilt orders silently become redeemable while yield has not exceeded 50% of principal, conflicting with "permanently exhausted".
  function _isFirstPosition(uint256 positionId) internal pure returns (bool) {
    return positionId == 0;
  }

  /// @dev First-order redemption entitlement status (structural determination, for frontend/indexer use)
  /// @return used       whether the first-order redemption entitlement is exhausted (redeemed or maxed out)
  /// @return redeemable whether redemption can be executed immediately right now
  /// @return flags      the flags of the first position (bit0 = closed, bit1 = not redeemable)
  /// Pitfall: this function **only does a structural determination** and does not compute the redeemable amount --
  ///       the amount depends on pending yield and updating the TWAP is a state change, which cannot be done in a view.
  function _firstRedeemStatus(address user) internal view returns (bool used, bool redeemable, uint8 flags) {
    FvUser storage fv = _fvUsers[user];
    if (fv.positions.length == 0) return (false, false, 0);
    Position storage p = fv.positions[0];
    flags = p.flags;
    if (flags & 1 != 0) return (true, false, flags);  // first order closed -> entitlement permanently exhausted
    if (flags & 2 != 0) return (true, false, flags);  // not-redeemable flag set -> entitlement exhausted
    if (block.timestamp < p.depositTime + GlobalConfig.LOCKUP_MIN) return (false, false, flags);
    return (false, true, flags);
  }

  function _register(address user, address referrer) internal {
    RefInfo storage r = _refs[user];
    if (r.flags & 1 != 0) return;
    if (user != address(0) && user == referrer) revert CoreVault_SelfReferral();
    address _ref = (referrer == address(0) || _refs[referrer].flags & 1 == 0) ? address(0) : referrer;
    r.referrer = _ref;
    // Pitfall: use |= rather than = -- preserves any existing bit1 (first deposit) / bit2 (entitlement closed) flags, avoiding an accidental clear.
    r.flags |= 1;
    if (!_hasUsers) _hasUsers = true;
    if (_ref != address(0)) _directReferrals[_ref].push(user);
    emit ReferralRegistered(user, _ref);
  }

  function _requireValidReferrer(address referrer) internal view {
    if (referrer == msg.sender) revert CoreVault_SelfReferral();
    if (referrer == address(0)) {
      if (!isRegistered(msg.sender) && _hasUsers)
        revert CoreVault_NoReferrer();
    } else {
      if (_hasUsers && !isRegistered(msg.sender) && !isRegistered(referrer))
        revert CoreVault_NoReferrer();
    }
  }

  function _markFirstInvest(address user) internal returns (bool) {
    RefInfo storage r = _refs[user];
    if (r.flags & 2 != 0) return false;
    r.flags |= 2;
    return true;
  }

  function _incValidDirects(address user) internal {
    RefInfo storage r = _refs[user];
    if (r.validDirectCount < 9) r.validDirectCount++;
  }

  function _syncLevel(address user, uint8 nl) internal {
    RefInfo storage r = _refs[user];
    if (nl > 9) nl = 9;
    if (nl > r.teamLevel) { r.teamLevel = nl; emit TeamLevelUp(user, nl); }
  }

  /// @dev Compute the level (0..9) from a **single module's** team performance
  function _levelFromTtu(uint256 ttu) internal view returns (uint8) {
    uint8 nl = 0;
    uint256[] storage thresholds = _teamThresholds;
    unchecked {
      for (uint8 l = 0; l < 10 && l < thresholds.length;) {
        if (ttu >= thresholds[l]) { nl = l; l++; }
        else break;
      }
    }
    return nl;
  }

  /// @dev Requirement 2.0: the three modules (farming / OSK staking / FIST staking) compute levels **independently**, and only the highest is synced.
  /// Pitfall (severe): do not add A+B staking performance together -- the requirement states "the three performances are all computed independently,
  ///   only the level is synced to the highest level". Adding them would let a user who **fails the threshold in each module individually** level up out of thin air,
  ///   and then claim excess team differential (fund leakage).
  function _effectiveLevel(address user) internal view returns (uint8) {
    uint8 lvFarm = _levelFromTtu(_fvUsers[user].totalTeamUsd);
    uint8 lvA    = _levelFromTtu(_modA[user].teamUsd);
    uint8 lvB    = _levelFromTtu(_modB[user].teamUsd);
    uint8 nl = lvFarm;
    if (lvA > nl) nl = lvA;
    if (lvB > nl) nl = lvB;
    return nl;
  }

  /// @dev The three modules' respective levels (for views/audits to verify independence)
  function _levelBreakdown(address user) internal view returns (uint8 lvFarm, uint8 lvA, uint8 lvB) {
    lvFarm = _levelFromTtu(_fvUsers[user].totalTeamUsd);
    lvA    = _levelFromTtu(_modA[user].teamUsd);
    lvB    = _levelFromTtu(_modB[user].teamUsd);
  }
}

