Contracts/CoreVaultReferral.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {OracleLib} from "../src/core/OracleLib.sol";
import {GlobalConfig} from "../src/core/GlobalConfig.sol";
import {YieldMath} from "../src/lib/YieldMath.sol";
import {CoreVaultAdmin} from "./CoreVaultAdmin.sol";

/// @title  CoreVaultReferral -- referral & team system
/// @notice Contains referral registration validation, team performance tracking, level promotion, and staking referral reward distribution.
/// @dev 3rd generation (facet split version) rewritten version -- for evidence and limitations see the top note of CoreVaultStorage.sol.
///      This file is **byte-for-byte identical** to the 2nd generation (blob fa821992d...) -- on-chain selector checks found no external
///      function additions or removals in this layer, and the per-pool semantics of `_checkStakingMaxOut` match its `src/` callers exactly.
abstract contract CoreVaultReferral is CoreVaultAdmin {

  // ════════════════════════════════════════════════════════════
  //  Staking performance tracking (writes to _modA / _modB)
  // ════════════════════════════════════════════════════════════

  function _updateTeamPerf(address user, uint256 usdAmount, TokenType t) internal {
    if (!isRegistered(user) || usdAmount == 0) return;
    mapping(address => ModValues) storage mods = (t == TokenType.A) ? _modA : _modB;
    ModValues storage m = mods[user];
    if (usdAmount <= m.maxUsd) return;
    unchecked {
      uint256 delta = usdAmount - m.maxUsd;
      m.maxUsd = usdAmount;
      bool isFirst = m.maxUsd == usdAmount && usdAmount == delta;
      address _ref = _refs[user].referrer;
      // Valid-user threshold (client ruling on 2026-09-27): this pool's staking lower bound is already validated at the `stakeA` / `stakeB`
      //   entry by **token count** (`MIN_STAKE_A` / `MIN_STAKE_B`, both 100 tokens), so no USD threshold is **layered on** here.
      // Pitfall: the previous single USD constant (`VALID_USER_MIN_USDT`) test would misjudge qualifying small stakes as invalid direct referrals
      //   (a token's USD value fluctuates with price, a different dimension from the "token-count lower bound").
      if (_ref != address(0) && isFirst) {
        if (_markFirstInvest(user)) {
          if (_refs[_ref].validDirectCount < GlobalConfig.MAX_REFERRAL_GEN) _incValidDirects(_ref);
        }
      }
      address curr = _ref;
      for (uint16 d = 0; d < GlobalConfig.MAX_TEAM_DEPTH && curr != address(0); d++) {
        ModValues storage cm = mods[curr];
        cm.teamUsd += delta;
        if (d == 0) cm.directUsd += delta;
        _checkLevelUpStaking(curr);
        curr = _refs[curr].referrer;
      }
    }
  }

  function _checkLevelUpStaking(address user) internal {
    uint8 curLv = _refs[user].teamLevel;
    if (curLv >= 9) return;
    uint8 nl = _effectiveLevel(user);
    if (nl > curLv) _syncLevel(user, nl);
  }

  // ════════════════════════════════════════════════════════════
  //  Staking reward distribution (direct referral / team differential)
  // ════════════════════════════════════════════════════════════

  function _distributeStakingRewards(address user, uint256 reward, TokenType t) internal {
    if (!isRegistered(user)) return;
    uint256 taxTotal = _distributeStakingLoop(user, reward, t);
    if (taxTotal > 0) {
      if (t == TokenType.A) totalAPoolRewards += taxTotal;
      else totalBPoolRewards += taxTotal;
    }
    // ── Node mining pool 30% dividend leg (system 2) -- the staking module also accrues it ──
    // Client-confirmed on 2026-09-23: coverage was expanded from "farming only" to "farming + staking".
    //   Evidence: `node-requirements-doc.txt` uses the wording "**network-wide** static revenue" (founder 5 / co-founder 5 / sponsor 10 / operation 10),
    //         while `development-requirements-doc-2.0.md:134-140` defines team rewards as "X% of **static revenue**",
    //         confirming that staking 7%/cycle is "static revenue" -> all three modules fall under "network-wide static revenue".
    // Base: the **USD equivalent** of this static yield. Pool A (OSK) yield is in OSK, pool B (FIST) yield is in FIST.
    // Token: `NodePoolDistributor` is **single-token immutable = OSK**, so pool B must be converted by value into OSK when transferred out:
    //         rewardUsd = reward × 1e18 / rate;  nodePoolOsk = rewardUsd × 30% × avgARate / 1e18.
    // Pitfall: the standard token->USD direction is `amount × 1e18 / rate` (same form as CoreVaultStaking.sol:55);
    //       never write `amount × rate / 1e18` -- that is the reverse USD->token direction and yields an off-by-orders-of-magnitude result.
    // Policy consistent with farming: additional expense (does not consume the user's 100%), does not participate in 3x max-out accounting, silently skipped when not wired.
    //   Regression: test/StakingNodePoolLeg.t.sol
    if (reward > 0) {
      (uint256 avgARate, uint256 avgBRate,) = OracleLib.getAccountingPrices(_oracle);
      uint256 rate = (t == TokenType.A) ? avgARate : avgBRate;
      uint256 rewardUsd = Math.mulDiv(reward, 1e18, rate, Math.Rounding.Floor);
      _payoutNodePoolLeg(rewardUsd, avgARate);
    }
  }

  function _distributeStakingLoop(address user, uint256 reward, TokenType t)
    internal returns (uint256 taxTotal)
  {
    uint256 dirRem = Math.mulDiv(reward, 3000, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
    uint256 teamPool = Math.mulDiv(reward, 7000, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
    uint256 teamRem = teamPool;
    uint256 redirected; // amount retained in this pool because the upline has no valid stake (original token, gross before tax)
    address current = _refs[user].referrer;
    uint8 maxDL;
    unchecked {
      for (uint16 d = 0; d < GlobalConfig.MAX_TEAM_DEPTH && current != address(0) && (dirRem > 0 || teamRem > 0); d++) {
        address upline = current;
        // Requirement (2026-09-26): an upline must have a **valid stake** in this pool to claim this pool's dynamic yield.
        //   Uplines who have not staked (farming only) / have maxed out (3x max-out clears orders) receive nothing, and their amount is **retained in this pool**
        //   to strengthen redemption capacity (no longer passed further up).
        // Note: a maxed-out user's order has been deleted => _hasValidStake is always false, so no separate rightsClosed case is needed.
        // Note: their level **still** participates in the maxDL differential chain computation -- to keep higher uplines' differential base from being wrongly raised
        //   (if the level were skipped too, higher uplines would receive excess differential).
        bool eligible = _hasValidStake(upline, t);
        {
          if (d < GlobalConfig.MAX_REFERRAL_GEN && dirRem > 0 && _refs[upline].validDirectCount >= d + 1) {
            uint256 rate = YieldMath.directReferralRate(uint8(d));
            if (rate > 0) {
              uint256 rA = Math.mulDiv(reward, rate, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
              if (rA > dirRem) rA = dirRem;
              if (eligible) {
                uint256 net = Math.mulDiv(rA, GlobalConfig.REFERRAL_NET_BP, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
                _payoutStaking(upline, net, t);
                _modEarnedDirect[upline] += net;
                _modEarnedDirectByPool[upline][t] += net; // measured per pool, for the 3x max-out determination
                taxTotal += rA - net;
                emit DirectRewardAccrued(upline, user, rA, uint8(d + 1));
              } else {
                // no valid stake -> skip payout, amount retained in this pool (not passed further up)
                redirected += rA;
                emit StakingRewardRedirected(upline, user, rA, t, 0);
              }
              dirRem -= rA;
            }
          }
        }
        {
          uint8 myLv = _refs[upline].teamLevel;
          if (myLv > maxDL) {
            uint256 diff = YieldMath.teamRate(myLv) - YieldMath.teamRate(maxDL);
            uint256 tA = Math.mulDiv(teamPool, diff, 7000, Math.Rounding.Floor);
            if (tA > teamRem) tA = teamRem;
            if (tA > 0) {
              if (eligible) {
                uint256 net = Math.mulDiv(tA, GlobalConfig.REFERRAL_NET_BP, GlobalConfig.RATE_PRECISION, Math.Rounding.Floor);
                _payoutStaking(upline, net, t);
                _modEarnedTeam[upline] += net;
                _modEarnedTeamByPool[upline][t] += net; // measured per pool, for the 3x max-out determination
                emit TeamRewardAccrued(upline, user, tA, myLv);
                taxTotal += tA - net;
              } else {
                // no valid stake -> skip payout, amount retained in this pool (the level still advances maxDL, see above)
                redirected += tA;
                emit StakingRewardRedirected(upline, user, tA, t, 1);
              }
              teamRem -= tA;
            }
            maxDL = myLv;
          }
        }
        // Requirement 2.0 sections 3/4: when a V1-or-above user's dynamic yield reaches 3x principal -> immediate max-out
        //   Pitfall: must come after this round's distribution -- pay out first, then judge, otherwise this round's yield would be under-counted/under-paid.
        if (_refs[upline].teamLevel >= GlobalConfig.MIN_MAXOUT_TEAM_LEVEL) {
          _checkStakingMaxOut(upline, t);
        }
        current = _refs[upline].referrer;
      }
    }
    // Retained in this pool: the reward is no longer transferred out and simply stays in this contract's balance -> strengthens that pool's redemption reserve; the counter is for audit only.
    if (redirected > 0) {
      if (t == TokenType.A) _redirectedToPoolA += redirected;
      else _redirectedToPoolB += redirected;
    }
  }

  // ════════════════════════════════════════════════════════════
  //  Requirement 2.0 sections 3/4: staking 3x max-out (V1+ only)
  // ════════════════════════════════════════════════════════════

  /// @dev Determine and execute a staking max-out (**per pool, independently**)
  /// @notice Trigger conditions (both must hold):
  ///   1) team level >= MIN_MAXOUT_TEAM_LEVEL (V1) -- users without a V level are **not subject** to the 3x max-out limit;
  ///   2) this pool's dynamic yield >= this pool's unsettled order principal × MAX_MULTIPLIER.
  /// @dev Policy (client-confirmed on 2026-09-23): the requirements' "team yield" = **9-generation direct referral reward + 7-level team reward**,
  ///      so dynamic here is `_modEarnedDirectByPool + _modEarnedTeamByPool` (the sum of both),
  ///      and both are **net (80%)** -- the 20% tax does not enter the personal accumulation.
  ///      Regression: test/ThreeXMaxOutAudit.t.sol::test_Staking_3x_UsesNetDynamic.
  /// Max-out actions: close **this pool's** orders (active + ready), **principal is not refunded**, close **this pool's** dynamic yield entitlement;
  ///           **this pool's already-generated static yield is deferred**, to be paid to the user when they rebuild a new position in this pool.
  /// Pitfall (severe): only the orders and entitlements of the passed pool t may be closed --
  ///   when an OSK stake meets the max-out condition, it must not affect the FIST stake or the farming module (the three compute performance independently).
  /// Pitfall: principal not refunded = do not call _payoutStaking, keeping the funds in this contract as a redemption reserve;
  ///       but _totalPoolA/_totalPoolB must be decremented in sync -- the principal has left the user's order, and not decrementing would overstate the pool accounting.
  /// Pitfall: the principal base uses active.principal + ready.principal (all unsettled orders of this pool), not just active,
  ///       otherwise the principal in ready would become a blind spot in the max-out determination.
  function _checkStakingMaxOut(address user, TokenType t) internal returns (bool exited) {
    StakeState storage s = (t == TokenType.A) ? _aStakes[user] : _bStakes[user];
    uint256 principal = s.active.principal + s.ready.principal;
    if (principal == 0) return false;
    uint256 dynamic = _dynamicEarnedByPool(user, t);
    if (dynamic < principal * GlobalConfig.MAX_MULTIPLIER) return false;

    // ── Requirement 2.0: static yield deferral (orders are closed but yield is not destroyed; paid when a new position is rebuilt) ──
    //   Policy exactly matches _unlockReady: use the shared _orderStaticYield to avoid the deferral/settlement policies diverging.
    //   Pitfall: must be computed before delete -- after deletion all order fields are zeroed and the yield can no longer be computed.
    //   Pitfall: for an order that has not completed a full cycle, the yield is 0 under the "per-cycle" rule (consistent with the existing locked behavior).
    uint256 deferred = _orderStaticYield(s.active.principal, s.active.endTime)
                     + _orderStaticYield(s.ready.principal, s.ready.endTime);
    if (deferred > 0) {
      unchecked { s.pendingStaticYield += deferred; }
      emit StakingYieldDeferred(user, t, deferred);
    }

    // ── Max-out: principal not refunded, this pool's orders closed ──
    (uint256 avgARate, uint256 avgBRate,) = OracleLib.getAccountingPrices(_oracle);
    uint256 rate = (t == TokenType.A) ? avgARate : avgBRate;
    if (rate > 0) {
      uint256 poolUsd = Math.mulDiv(principal, 1e18, rate, Math.Rounding.Floor);
      if (t == TokenType.A) {
        if (poolUsd < _totalPoolA) _totalPoolA -= poolUsd; else _totalPoolA = 0;
      } else {
        if (poolUsd < _totalPoolB) _totalPoolB -= poolUsd; else _totalPoolB = 0;
      }
    }
    delete s.active;
    delete s.ready;
    // Only close **this pool's** entitlement bit (A->bit2 / B->bit3); the other pool's entitlement bit stays as is
    _refs[user].flags |= _stakeRightsBit(t);
    emit StakingMaxOut(user, t, principal, dynamic);
    return true;
  }
}

src/core/CoreVaultViewFacet.sol.content:
// src/core/CoreVaultViewFacet.sol
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {CoreVaultStorage} from "../../Contracts/CoreVaultStorage.sol";
import {OracleLib} from "./OracleLib.sol";
import {GlobalConfig} from "./GlobalConfig.sol";

/// @title  CoreVaultViewFacet -- CoreVault's **read-only view facet**
/// @notice Carries all of CoreVault's external view functions, called by CoreVault via `DELEGATECALL`.
///
/// @dev ===== design rationale (size constraint, must be understood) =====
/// The runtime bytecode of the CoreVault inheritance chain once reached **30,747 bytes**, exceeding the EIP-170 limit (24,576),
/// so it **could not be deployed** on BSC mainnet. Per-layer measurements showed the bottleneck was concentrated in the view and staking layers.
/// This contract inherits `CoreVaultStorage` -> **its storage layout is identical to CoreVault's**;
/// when called by CoreVault via `DELEGATECALL`, it reads and writes CoreVault's storage slots -- so the view logic
/// could be moved out as-is, with external callers (frontend / CoreVaultViewer / tests) **needing no changes at all**.
///
/// @dev ===== pitfalls =====
/// (1) **Do not inherit the CoreVault body** -- that would pull all the business code back and lose the slimming benefit.
///    Inherit only `CoreVaultStorage` (pure storage + events + errors + internal helpers).
/// (2) **Layout consistency is a hard constraint** -- this contract's inheritance chain must exactly match CoreVault's storage prefix.
///    CoreVault is: CoreVaultStorage -> CoreVaultAdmin -> ... , while this contract is: CoreVaultStorage.
///    Since CoreVaultAdmin and the layers after it **add no state variables** (functions only), the two layouts are the same.
///    If state variables are ever added in Admin/Referral/..., they **must also be declared here**, otherwise the views read the wrong slots.
/// (3) `getFarmingRaw` **no longer uses a hard-coded storage slot** -- the original relied on `keccak256(abi.encode(u, 45))`,
///    but that slot number's premise "aToken/bToken/treasury are immutable (occupy no slot)" no longer holds after the module split
///    (the three must become ordinary storage variables, shifting all slot numbers by 3). It now **reads the mapping directly** `_fvUsers[u]`,
///    fully decoupled from the layout -- see the note at `getFarmingRaw` in this file.
/// (4) This contract is **read-only**: it contains no state-changing function. If write logic were mistakenly added, it would modify
///    CoreVault's real storage via DELEGATECALL -- a high-severity error.
contract CoreVaultViewFacet is CoreVaultStorage {
    // ════════════════════════════════════════════════════════════
    //  Staking views (moved out of CoreVaultStaking)
    // ════════════════════════════════════════════════════════════

    function activeOrder(address user, uint8 t) external view returns (
        uint256 principal, uint256 endTime, uint8 flags
    ) {
        StakeState storage s = t == 0 ? _aStakes[user] : _bStakes[user];
        return (s.active.principal, s.active.endTime, s.active.flags);
    }

    function getModValues(address user) external view returns (
        uint256 teamA, uint256 teamB, uint256 directA, uint256 directB,
        uint256 maxA, uint256 maxB, uint256 earnedDirect, uint256 earnedTeam
    ) {
        teamA = _modA[user].teamUsd;
        directA = _modA[user].directUsd;
        maxA = _modA[user].maxUsd;
        teamB = _modB[user].teamUsd;
        directB = _modB[user].directUsd;
        maxB = _modB[user].maxUsd;
        earnedDirect = _modEarnedDirect[user];
        earnedTeam = _modEarnedTeam[user];
    }

    function totalEarnedAllStaking(address u) external view returns (uint256) {
        return _aStakes[u].totalEarned + _bStakes[u].totalEarned;
    }

    function getTotalPoolA() external view returns (uint256) {
        return _totalPoolA;
    }

    function getTotalPoolB() external view returns (uint256) {
        return _totalPoolB;
    }

    /// @dev Cumulative donated amount for this pool (measured in the original token) -- strictly separated from the principal pools _totalPoolA/B
    /// @param t 0 = OSK(A) staking pool, 1 = FIST(B) staking pool
    function getTotalDonated(uint8 t) external view returns (uint256) {
        return t == 0 ? _totalDonatedA : _totalDonatedB;
    }

    /// @dev Cumulative reward amount "retained in this pool because the upline had no valid stake" (measured in the original token).
    ///      Source: in `_distributeStakingLoop`, the upline has not staked / has maxed out -> skip payout, amount retained in this pool.
    /// Pitfall: strictly separated from `getTotalDonated` -- the former is an external donation, this is retained reward; different sources must not be merged.
    /// @param t 0 = OSK(A) staking pool, 1 = FIST(B) staking pool
    function getTotalRedirected(uint8 t) external view returns (uint256) {
        return t == 0 ? _redirectedToPoolA : _redirectedToPoolB;
    }

    /// @dev This pool's **actual redemption reserve** (the contract's balance of that token)
    ///      Pitfall: returns only the balance, with no USD conversion -- conversion requires reading the oracle, a state change, which cannot be done in a view.
    function getPoolReserve(uint8 t) external view returns (uint256) {
        return t == 0 ? IERC20(address(aToken)).balanceOf(address(this))
                      : IERC20(address(bToken)).balanceOf(address(this));
    }

    /// @dev Whether this pool's staking dynamic yield entitlement is closed (true after 3x max-out, restored after rebuilding a new order in this pool)
    /// Pitfall: must be queried per pool -- an OSK max-out does not affect FIST entitlements.
    function isStakingRightsClosed(address u, uint8 t) external view returns (bool) {
        return _stakingRightsClosed(u, t == 0 ? TokenType.A : TokenType.B);
    }

    /// @dev This pool's total dynamic yield (direct referral reward + team differential), denominated in that pool's token amount
    function getStakingDynamicEarned(address u, uint8 t) external view returns (uint256) {
        return _dynamicEarnedByPool(u, t == 0 ? TokenType.A : TokenType.B);
    }

    /// @dev This pool's **pending static yield to be paid** (deferred at max-out, paid when a new position is rebuilt in this pool)
    function getPendingStaticYield(address u, uint8 t) external view returns (uint256) {
        StakeState storage s = (t == 0) ? _aStakes[u] : _bStakes[u];
        return s.pendingStaticYield;
    }

    /// @dev This pool's 3x max-out progress: (accumulated dynamic yield, max-out threshold)
    function getStakingMaxOutProgress(address u, uint8 t)
        external view returns (uint256 dynamicEarned, uint256 threshold)
    {
        TokenType tt = t == 0 ? TokenType.A : TokenType.B;
        StakeState storage s = (tt == TokenType.A) ? _aStakes[u] : _bStakes[u];
        dynamicEarned = _dynamicEarnedByPool(u, tt);
        threshold = (s.active.principal + s.ready.principal) * GlobalConfig.MAX_MULTIPLIER;
    }

    /// @dev Three-module 3x max-out overview: the independent status of farming / OSK staking / FIST staking
    function getThreeSectorStatus(address u) external view returns (
        bool farmExited, bool oskRightsClosed, bool fistRightsClosed,
        uint256 farmTtu, uint256 oskTtu, uint256 fistTtu,
        uint8 lvFarm, uint8 lvOsk, uint8 lvFist, uint8 syncedLevel
    ) {
        farmExited = _fvUsers[u].flags & 1 != 0;
        oskRightsClosed = _stakingRightsClosed(u, TokenType.A);
        fistRightsClosed = _stakingRightsClosed(u, TokenType.B);
        farmTtu = _fvUsers[u].totalTeamUsd;
        oskTtu = _modA[u].teamUsd;
        fistTtu = _modB[u].teamUsd;
        (lvFarm, lvOsk, lvFist) = _levelBreakdown(u);
        syncedLevel = _refs[u].teamLevel;
    }

    // ════════════════════════════════════════════════════════════
    //  Farming / referral views (moved out of CoreVaultFarmingReferral)
    // ════════════════════════════════════════════════════════════

    function getRefInfo(address user) external view returns (address referrer, uint8 teamLevel, uint8 validDirectCount, uint8 flags) {
        RefInfo storage r = _refs[user];
        return (r.referrer, r.teamLevel, r.validDirectCount, r.flags);
    }

    function positionCount(address user) external view returns (uint256) {
        return _fvUsers[user].positions.length;
    }

    function getDirectReferralAt(address u, uint256 i) external view returns (address) {
        return _directReferrals[u][i];
    }

    function getDirectReferralsCount(address u) external view returns (uint256) {
        return _directReferrals[u].length;
    }

    /// @dev Pitfall: the original implementation used a **hard-coded storage slot 45** (`keccak256(abi.encode(u, 45))`) to read FvUser --
    ///      that slot number relied on the premise "aToken/bToken/treasury are immutable (occupy no slot)".
    ///      After the module split the three must become ordinary storage variables (immutable cannot be shared via delegatecall),
    ///      so all slot numbers shifted and the hard-coding immediately broke. Hence it now **reads the mapping directly** -- decoupled from the layout, never mismatching.
    function getFarmingRaw(address u) external view returns (
        uint256 invested, uint256 team, uint256 direct, uint256 earnedD, uint256 earnedT
    ) {
        FvUser storage fv = _fvUsers[u];
        return (fv.totalInvestedUsd, fv.totalTeamUsd, fv.totalDirectUsd, fv.earnedDirect, fv.earnedTeam);
    }

    function getPositionRaw(address u, uint256 pid) external view returns (
        uint256, uint256, uint256, uint256
    ) {
        if (pid >= _fvUsers[u].positions.length) return (0, 0, 0, 0);
        Position storage p = _fvUsers[u].positions[pid];
        return (p.principalUsd, p.earnedUsd, p.snapshotDirect, p.snapshotTeam);
    }

    function getPositionFlags(address u, uint256 pid) external view returns (uint8) {
        if (pid >= _fvUsers[u].positions.length) return 0;
        return _fvUsers[u].positions[pid].flags;
    }

    /// @dev Requirement 2.0 section 2: position deposit token (0 = BNB, 1 = FIST)
    function getPositionDepositToken(address u, uint256 pid) external view returns (uint8) {
        if (pid >= _fvUsers[u].positions.length) return 0;
        return _fvUsers[u].positions[pid].depositToken;
    }

    /// @dev Requirement 2.0 section 2: first-order redemption entitlement status
    function getFirstRedeemStatus(address u) external view returns (bool used, bool redeemable, uint8 flags) {
        return _firstRedeemStatus(u);
    }

    function totalFarmingEarned(address u) external view returns (uint256) {
        return _fvUsers[u].totalEarned;
    }

    function getEffectiveLevel(address user) external view returns (uint8) {
        return _effectiveLevel(user);
    }

    function getFvUserMaxAndFlags(address u) external view returns (uint256 maxUsd, uint8 fvFlags) {
        FvUser storage fv = _fvUsers[u];
        return (fv.maxUsd, fv.flags);
    }

    /// @dev Direct referral summary (paginated)
    function getDirectReferralSummary(address user, uint256 offset, uint256 limit) external view returns (
        address[] memory refs,
        uint256[] memory farmingInvested,
        uint256[] memory farmingTeam,
        uint256[] memory stakingTeamA,
        uint256[] memory stakingTeamB
    ) {
        uint256 total = _directReferrals[user].length;
        if (offset >= total) {
            refs = new address[](0);
            farmingInvested = new uint256[](0);
            farmingTeam = new uint256[](0);
            stakingTeamA = new uint256[](0);
            stakingTeamB = new uint256[](0);
            return (refs, farmingInvested, farmingTeam, stakingTeamA, stakingTeamB);
        }
        uint256 end = offset + limit;
        if (end > total) end = total;
        uint256 n = end - offset;
        refs = new address[](n);
        farmingInvested = new uint256[](n);
        farmingTeam = new uint256[](n);
        stakingTeamA = new uint256[](n);
        stakingTeamB = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            address r = _directReferrals[user][offset + i];
            refs[i] = r;
            farmingInvested[i] = _fvUsers[r].totalInvestedUsd;
            farmingTeam[i] = _fvUsers[r].totalTeamUsd;
            stakingTeamA[i] = _modA[r].teamUsd;
            stakingTeamB[i] = _modB[r].teamUsd;
        }
    }

    // ════════════════════════════════════════════════════════════
    //  Price views
    // ════════════════════════════════════════════════════════════
    // Note: `getSwapPrices` is **not declared here** -- it is a required implementation of `IAccounting`, kept in CoreVault
    //   (otherwise the interface would be unsatisfied -> CoreVault becomes abstract). It is not redeclared here to avoid an override conflict.
}

Contracts/CoreVaultLogicFacet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {CoreVaultFarmingReferral} from "./CoreVaultFarmingReferral.sol";

/// @title  CoreVaultLogicFacet -- CoreVault's **business logic facet** (farming module + op dispatch)
/// @notice Called by `CoreVault` via `DELEGATECALL`. The inheritance chain
///         `CoreVaultStorage -> Admin -> Referral -> Staking -> Farming -> FarmingReferral`
///         means the **storage layout is identical to CoreVault**, so it reads and writes CoreVault's storage slots.
///
/// @dev ===== this file is a 3rd generation (facet split version) **rewrite** -- evidence and limitations =====
/// This file **does not exist** in the 2nd generation (it was still monolithic then), nor does it appear in `archive/cgbb1_diff.txt`
/// (`git diff HEAD` does not include untracked new files -- ironclad evidence: the diff's added lines reference
/// `src/interfaces/IFISTDAO.sol` yet it was never created). So it is rewritten here from the following evidence:
///   (1) the **construction and forwarding contract** of `src/CoreVault.sol`:
///      `logicFacet = address(new CoreVaultLogicFacet(vf))` -- the constructor argument is the viewFacet address;
///      `fallback() external payable { _fwdLogic(); }` -- the raw calldata is delegatecalled in full to this contract;
///      plus 6 "farming module wrappers" (`depositBNB` / `depositFIST` / `claimYield` /
///      `claimYieldActive` / `redeemPrincipal` / `redeemPrincipalActive`) that also forward to this contract.
///   (2) the top comment of `src/CoreVault.sol` states this contract's responsibility:
///      "CoreVaultLogicFacet = Storage->Admin->Referral->Farming->FarmingReferral (farming + op dispatch)".
///   (3) the on-chain 9/21 deployment's **measured function selectors**: `logicFacet()` (72f70be2) / `viewFacet()` (30becb34)
///      hit; `depositFIST(address,uint256)` (30d931f1) / `setDepositBounds(...)` (92736b07) hit.
///   (4) the **op multiplexing** implementation of the 2nd generation `src/CoreVault.sol`'s `fallback()` (byte-for-byte reconstructed version) --
///      this file's op semantics are equivalent to it, only swapping the implementation bodies such as `_depositBNBCore` for the versions **inherited** by this contract.
/// WARNING: therefore this file is **not** a verbatim copy of the original 3rd generation source, but a "reconstruction under evidence constraints".
///    The original 3rd generation real source must still be retrieved from an external source before it can serve as an audit baseline.
contract CoreVaultLogicFacet is CoreVaultFarmingReferral {

  /// @dev View facet address (passed in at CoreVault construction time) -- exposed externally to preserve the construction contract and verifiability.
  ///      This contract **does not forward** view calls: CoreVault's view wrappers call `_fwdView()` directly to the viewFacet,
  ///      bypassing this contract; so it merely holds the address and does not participate in routing.
  address public immutable viewFacet;

  constructor(address vf) {
    viewFacet = vf;
  }

  // ════════════════════════════════════════════════════════════
  //  Farming module entry points (depositBNB / depositFIST / claimYield /
  //  claimYieldActive / redeemPrincipal / redeemPrincipalActive)
  // ════════════════════════════════════════════════════════════
  // Note: these 6 functions are provided by the inheritance chain (`CoreVaultFarming`) and are all `external` --
  //   CoreVault's same-named wrappers delegatecall the raw calldata in full, with selectors matching one to one,
  //   so **no redeclaration is needed** here (redeclaring would instead conflict with the inherited definitions).

  // ════════════════════════════════════════════════════════════
  //  Fallback -- op multiplexing entry point
  //  length 1  : op byte only
  //  length 21 : op + address(referrer)
  //  length 33 : op + uint256(positionId)
  //  0x01 = depositBNB | 0x02 = claimYield | 0x03 = redeemPrincipal
  // ════════════════════════════════════════════════════════════
  // Design intent: a gas-cheap compact call format -- the frontend can complete a deposit with 1 byte of calldata,
  //   without an ABI-encoded 4-byte selector + 32-byte aligned arguments.
  // Pitfall: standard ABI calls **do not** reach here -- CoreVault's named wrappers already capture those selectors.
  // Pitfall: all three ops' implementations depend on the farming layer (_depositBNBCore/_claimYieldCore/_redeemPrincipalCore),
  //   which is exactly why "the farming module must be placed in the same facet as op dispatch": if placed in viewFacet or CoreVault,
  //   it would pull the entire Farming layer back, losing the slimming benefit.
  fallback() external payable {
    if (msg.data.length == 0) revert CoreVault_InvalidAmount();
    uint8 op = uint8(msg.data[0]);
    _guardEnter();
    if (op == 0x02) {
      // claimYield: when BNB is attached, forward it to the insurance pool as well -- **deliberate design** (client-confirmed on 2026-09-24).
      //   WARNING: different from a "bare transfer": a bare transfer is a **mistaken operation with no calldata** (now rejected);
      //      while op 0x02/0x03 carrying BNB is a **call that explicitly carries business intent** --
      //      the caller has specified the op, and the attached BNB is treated as a donation/injection to the insurance pool, forwarded by this function.
      //   Pitfall: do not change it to revert along with the "bare transfer" -- that would break this business path.
      //   Zero-address protection: `_forwardBnbToInsurancePool` explicitly reverts when not wired (avoiding a fund black hole).
      _forwardBnbToInsurancePool();
      uint256 pid = msg.data.length >= 33
        ? uint256(bytes32(msg.data[1:33]))
        : _findActivePosition(msg.sender);
      _claimYieldCore(msg.sender, pid);
    } else if (op == 0x03) {
      // redeemPrincipal: same as above -- a call explicitly carrying an op; attached BNB is forwarded to the insurance pool
      _forwardBnbToInsurancePool();
      uint256 pid = msg.data.length >= 33
        ? uint256(bytes32(msg.data[1:33]))
        : _findActivePosition(msg.sender);
      _redeemPrincipalCore(msg.sender, pid);
    } else if (op == 0x01) {
      // depositBNB: referrer resolution and validation -- equivalent item by item to the 2nd generation
      address referrer;
      if (msg.data.length >= 21) referrer = address(bytes20(msg.data[1:21]));
      if (referrer == msg.sender) { _guardExit(); revert CoreVault_SelfReferral(); }
      if (referrer == address(0)) {
        if (!isRegistered(msg.sender) && _hasUsers) { _guardExit(); revert CoreVault_NoReferrer(); }
        referrer = _refs[msg.sender].referrer;
      } else {
        if (_hasUsers && !isRegistered(msg.sender) && !isRegistered(referrer)) { _guardExit(); revert CoreVault_NoReferrer(); }
      }
      _depositBNBCore(msg.sender, msg.value, referrer);
    } else {
      _guardExit();
      revert CoreVault_UnknownOp(op);
    }
    _guardExit();
  }

  // ════════════════════════════════════════════════════════════
  //  Bare BNB rejection
  // ════════════════════════════════════════════════════════════
  // Design intent: this contract **should not** directly hold BNB -- all its entry points go through CoreVault's DELEGATECALL,
  //   where `address(this)` is CoreVault, the funds belong to CoreVault, and this contract's address is irrelevant.
  //   If someone sends BNB directly to this contract's address, it is a mistaken operation; revert explicitly to avoid funds lingering at an unmanaged address.
  // Note: with a payable fallback but no receive, empty calldata goes to the fallback and reverts due to
  //   `msg.data.length == 0`; declaring receive explicitly here writes that semantics into the ABI layer.
  receive() external payable {
    revert CoreVault_InvalidAmount();
  }

  /// @dev Forward BNB attached to an op call to the insurance pool -- **a deliberate business path** (client-confirmed on 2026-09-24).
  ///   Semantics: the caller has explicitly expressed business intent via `op`; the attached BNB is treated as an injection into the insurance pool, forwarded by this function.
  ///   WARNING: distinguished from a "bare transfer" (empty calldata): the latter is a **mistaken operation with no intent**, already changed to
  ///      an explicit rejection in `CoreVault.receive()`; this path **keeps** forwarding.
  /// Pitfall: when `insurancePool` is not wired, **revert explicitly** rather than silently swallowing -- otherwise the BNB would linger in CoreVault
  ///   with no accounting, a fund black hole.
  function _forwardBnbToInsurancePool() private {
    if (msg.value == 0) return;
    address ip = insurancePool;
    if (ip == address(0)) revert CoreVault_ZeroAddress();
    (bool ok,) = payable(ip).call{value: msg.value}("");
    if (!ok) revert CoreVault_InvalidAmount();
  }
}

